-- RN Master standalone MC/SATA pilot import. Source: user-provided 1000-question RN master bank.
begin;
do $$
declare r record; qid uuid; qvid uuid; optrec record; n int; keyarr text[]; kc int;
begin
for r in select * from (values
('Set22-RN-1','Management of Care','Prioritization: home health','single_best_answer','Management of Care • Prioritization: home health • Multiple choice A home health nurse is planning visits for the day. Which client should the nurse visit first?','A client with heart failure who called to report a 3-lb weight gain overnight and new shortness of breath when lying down|A client with a healing venous leg ulcer due for a weekly dressing change|A client with type 2 diabetes who needs a monthly medication review|A client recovering from a hip replacement who has a scheduled physical therapy visit','A','Rapid weight gain with new orthopnea indicates worsening heart failure that may require urgent intervention. The other visits are routine.','Integrated','Management of Care'),
('Set22-RN-2','Physiological Adaptation','Hypertrophic cardiomyopathy','single_best_answer','Physiological Adaptation • Hypertrophic cardiomyopathy • Multiple choice A young adult is diagnosed with hypertrophic cardiomyopathy. Which instruction should the nurse include?','"Take nitroglycerin for chest pain."|"Stay well hydrated and avoid strenuous competitive sports as directed by your cardiologist."|"Take a sauna daily to relax the heart."|"Dehydration will improve your symptoms."','B','Dehydration, vasodilators, and intense exertion can worsen outflow obstruction and trigger syncope or sudden death. Beta blockers are commonly prescribed, and first-degree relatives should be screened.','Integrated','Adult Health'),
('Set22-RN-3','Health Promotion and Maintenance','Endocarditis prophylaxis','single_best_answer','Health Promotion and Maintenance • Endocarditis prophylaxis • Multiple choice A client with a prosthetic heart valve is scheduled for a dental cleaning. What should the nurse advise?','"No special precautions are needed."|"Tell your dentist about your valve. You will likely need antibiotics before dental procedures to prevent endocarditis."|"Avoid all dental care."|"Stop your anticoagulant for a week before the cleaning without asking your provider."','B','Clients at highest risk, including those with prosthetic valves, receive antibiotic prophylaxis before dental procedures that manipulate gum tissue. Anticoagulant changes are made only with provider direction.','Integrated','Fundamentals'),
('Set22-RN-4','Health Promotion and Maintenance','Pertussis prevention','single_best_answer','Health Promotion and Maintenance • Pertussis prevention • Multiple choice A client at 30 weeks'' gestation asks why she should receive the Tdap vaccine. What is the nurse''s best response?','"It protects you from tetanus only."|"Antibodies you make pass to your baby and help protect against whooping cough in the first months, before the baby can be vaccinated."|"It''s only needed if you''ve never had it."|"It should be given after delivery instead."    ','B','Tdap is recommended during each pregnancy, ideally between 27 and 36 weeks, to transfer protective antibodies. Pertussis is most dangerous for young infants.','Integrated','Fundamentals'),
('Set22-RN-5','Health Promotion and Maintenance','Travel-related VTE','single_best_answer','Health Promotion and Maintenance • Travel-related VTE • Multiple choice A client with a history of DVT is planning a 12-hour flight. Which advice should the nurse give?','"Stay seated the whole flight to avoid falls."|"Walk and do calf exercises periodically, stay hydrated, avoid alcohol, and wear compression stockings if prescribed."|"Take a sleeping pill so you can sleep through the flight."|"Cross your legs to stay comfortable."','B','Prolonged immobility increases VTE risk. Movement, hydration, and compression promote venous return. Sedation reduces movement.','Integrated','Fundamentals'),
('Set22-RN-6','Pharmacological and Parenteral Therapies','Myasthenia gravis drug interactions','single_best_answer','Pharmacological and Parenteral Therapies • Myasthenia gravis drug interactions • Multiple choice A client with myasthenia gravis has a new infection. Which prescription should the nurse question?','IV gentamicin|Acetaminophen for fever|IV fluids|Pyridostigmine as scheduled','A','Aminoglycosides, fluoroquinolones, magnesium, and some other drugs can impair neuromuscular transmission and precipitate myasthenic crisis.','Integrated','Pharmacology'),
('Set22-RN-7','Pharmacological and Parenteral Therapies','Carbamazepine','single_best_answer','Pharmacological and Parenteral Therapies • Carbamazepine • Multiple choice A client is starting carbamazepine for seizures. Which instruction should the nurse include?','"No blood tests are needed."|"Report sore throat, fever, easy bruising, or any rash right away, and keep appointments for blood tests."|"Drink grapefruit juice daily."|"Stop it suddenly if you feel drowsy."','B','Carbamazepine can cause blood dyscrasias and severe skin reactions such as SJS, especially in people of Asian ancestry who carry HLA-B*1502. Grapefruit raises drug levels, and abrupt withdrawal can trigger seizures.','Integrated','Pharmacology'),
('Set22-RN-8','Pharmacological and Parenteral Therapies','Levothyroxine in older adults','single_best_answer','Pharmacological and Parenteral Therapies • Levothyroxine in older adults • Multiple choice A 78-year-old client with coronary artery disease is starting levothyroxine for hypothyroidism. What does the nurse anticipate?','A full replacement dose on the first day|A low starting dose increased gradually, with teaching to report chest pain or palpitations|Stopping the client''s cardiac medications|Taking it with calcium for better absorption    ','B','Rapidly increasing metabolism raises myocardial oxygen demand and can trigger angina or MI in older adults with heart disease.','Integrated','Pharmacology'),
('Set22-RN-9','Physiological Adaptation','Esophageal atresia','single_best_answer','Physiological Adaptation • Esophageal atresia • Multiple choice A newborn has excessive frothy drooling and coughs, chokes, and turns blue with the first feeding. What should the nurse do?','Try feeding again more slowly|Stop feeding, keep the newborn NPO, suction the mouth, position with the head elevated, and notify the provider|Give water instead of formula|Place the newborn prone and continue feeding','B','These findings suggest esophageal atresia with tracheoesophageal fistula. Feeding risks aspiration. Diagnosis is confirmed when a catheter cannot pass into the stomach, and surgery is required.','Integrated','Adult Health'),
('Set22-RN-10','Physiological Adaptation','AKI recovery','single_best_answer','Physiological Adaptation • AKI recovery • Multiple choice A client recovering from acute kidney injury now has urine output of 4 L/day. Which complication should the nurse monitor for?','Fluid overload|Dehydration and electrolyte losses such as hypokalemia|Hyperkalemia only|Hypertension from excess fluid','B','During the diuretic phase, the tubules cannot yet concentrate urine, causing large fluid and electrolyte losses. Close monitoring of I&O, weight, and electrolytes is needed.','Integrated','Adult Health'),
('Set22-RN-11','Pharmacological and Parenteral Therapies','Anticholinergics in older adults','single_best_answer','Pharmacological and Parenteral Therapies • Anticholinergics in older adults • Multiple choice An 82-year-old client started oxybutynin for overactive bladder 1 week ago. The family reports new confusion and constipation. What should the nurse do?','Reassure the family that this is normal aging|Report the findings, because anticholinergic effects may be causing them|Increase the dose|Add a sedative for the confusion','B','Anticholinergic drugs cause confusion, constipation, urinary retention, dry mouth, and falls in older adults. They are on the Beers Criteria list. Alternatives may be considered.','Integrated','Pharmacology'),
('Set22-RN-12','Health Promotion and Maintenance','Acute low back pain','single_best_answer','Health Promotion and Maintenance • Acute low back pain • Multiple choice A client with acute, nonspecific low back pain and no red-flag symptoms asks about activity. What should the nurse recommend?','"Stay in bed for 2 weeks."|"Stay as active as tolerated, use heat for comfort, and gradually return to usual activities."|"Avoid all movement until the pain is completely gone."|"Lift heavy objects to strengthen your back."    ','B','Evidence supports staying active over bed rest for acute low back pain. Red flags such as bowel or bladder changes, saddle numbness, or leg weakness require urgent evaluation.','Integrated','Fundamentals'),
('Set22-RN-13','Pharmacological and Parenteral Therapies','IV iron','single_best_answer','Pharmacological and Parenteral Therapies • IV iron • Multiple choice A client is receiving the first dose of IV iron dextran. Which action is most important?','Give the full dose rapidly|Administer a test dose per protocol and monitor closely for anaphylaxis, with emergency equipment available|Give it intramuscularly instead|Mix it with other IV medications','B','Iron dextran carries a risk of serious hypersensitivity reactions. A test dose and close observation are required, and newer IV iron formulations have lower risk.','Integrated','Pharmacology'),
('Set22-RN-14','Reduction of Risk Potential','Bone marrow biopsy','single_best_answer','Reduction of Risk Potential • Bone marrow biopsy • Multiple choice A client has just had a bone marrow aspiration and biopsy from the posterior iliac crest. Which action should the nurse take?','Have the client walk immediately|Apply pressure to the site and monitor for bleeding and pain|Remove the dressing after 10 minutes|Place a heating pad on the site','B','Pressure and monitoring prevent hematoma, especially in clients with low platelets. Mild aching is expected, and increasing pain or bleeding should be reported.','Integrated','Adult Health'),
('Set22-RN-15','Health Promotion and Maintenance','Asplenia','single_best_answer','Health Promotion and Maintenance • Asplenia • Multiple choice A client is recovering from a splenectomy after trauma. Which teaching is most important?','"You are not at increased risk of infection."|"You will need pneumococcal, meningococcal, and Hib vaccines, and should seek care immediately for any fever."|"Avoid all vaccines."|"Fever is expected for months after surgery."','B','Without a spleen, clients are at risk for overwhelming infection from encapsulated bacteria. Vaccination and prompt treatment of fever are essential.','Integrated','Fundamentals'),
('Set22-RN-16','Pharmacological and Parenteral Therapies','Bupropion','single_best_answer','Pharmacological and Parenteral Therapies • Bupropion • Multiple choice A client with bulimia nervosa and depression is prescribed bupropion. What should the nurse do?','Administer the medication|Question the prescription, because bupropion is contraindicated in eating disorders due to seizure risk|Give it with alcohol to improve absorption|Double the dose for faster effect    ','B','Bupropion lowers the seizure threshold. Clients with bulimia or anorexia have a higher seizure risk, especially with electrolyte disturbances.','Integrated','Pharmacology'),
('Set22-RN-17','Physiological Adaptation','Mastitis','single_best_answer','Physiological Adaptation • Mastitis • Multiple choice A breastfeeding client at 3 weeks postpartum has a red, tender, warm area on one breast and a temperature of 101.8°F (38.8°C). Which instruction should the nurse give?','"Stop breastfeeding immediately."|"Continue breastfeeding or pumping, take the full course of prescribed antibiotics, rest, and drink fluids."|"Bind your breasts tightly."|"Only feed from the unaffected breast until the fever is gone."','B','Continued milk removal prevents stasis and abscess formation. The breast milk is safe for the infant. Antibiotics are completed as prescribed.','Integrated','Adult Health'),
('Set22-RN-18','Physiological Adaptation','Insulin needs in pregnancy','single_best_answer','Physiological Adaptation • Insulin needs in pregnancy • Multiple choice A client with type 1 diabetes is at 30 weeks'' gestation. How do her insulin needs typically change?','Insulin needs decrease throughout pregnancy|Insulin needs often increase in the second and third trimesters and then drop sharply after delivery|Insulin needs stay the same|Insulin is stopped in the third trimester','B','Placental hormones cause insulin resistance that increases as pregnancy progresses. After the placenta is delivered, insulin needs fall rapidly, raising the risk of hypoglycemia.','Integrated','Adult Health'),
('Set22-RN-19','Health Promotion and Maintenance','Congenital hypothyroidism','single_best_answer','Health Promotion and Maintenance • Congenital hypothyroidism • Multiple choice A newborn''s screening test confirms congenital hypothyroidism. Which instruction should the nurse give the parents?','"The medication is only needed for a few months."|"Give levothyroxine every day. Crush the tablet and mix it with a small amount of breast milk, formula, or water, not a full bottle."|"Mix it with soy formula for better absorption."|"Skip doses if the baby is sleeping."  ','B','Early, lifelong replacement prevents intellectual disability and growth problems. Mixing with a small volume ensures the whole dose is taken. Soy and iron can interfere with absorption.','Integrated','Fundamentals'),
('Set23-RN-1','Management of Care','Prioritization: PACU','single_best_answer','Management of Care • Prioritization: PACU • Multiple choice The nurse in the postanesthesia care unit (PACU) is caring for four clients. Which client should the nurse assess first?','A client extubated 5 minutes ago who has high-pitched inspiratory stridor and suprasternal retractions|A client who reports incisional pain of 6/10|A client who is shivering and asking for a warm blanket|A client who is drowsy but arousable with SpO2 96% on room air','A','Stridor with retractions after extubation suggests laryngospasm or laryngeal edema, an airway emergency. Pain and shivering need attention but are not life-threatening.','Integrated','Management of Care'),
('Set23-RN-2','Physiological Adaptation','Malignant hyperthermia','single_best_answer','Physiological Adaptation • Malignant hyperthermia • Multiple choice During surgery under general anesthesia, a client develops jaw muscle rigidity, rising end-tidal CO2, tachycardia, and a rapidly increasing temperature. Which medication does the nurse anticipate?','Dantrolene IV|Succinylcholine|Acetaminophen|Naloxone','A','These are signs of malignant hyperthermia, a genetic reaction to volatile anesthetics or succinylcholine. The triggering agents are stopped, and dantrolene is given along with cooling measures. A rising end-tidal CO2 is often the earliest sign.','Integrated','Adult Health'),
('Set23-RN-3','Reduction of Risk Potential','Moderate sedation','single_best_answer','Reduction of Risk Potential • Moderate sedation • Multiple choice During a colonoscopy with moderate (procedural) sedation using midazolam and fentanyl, which finding requires immediate intervention?','The client responds to verbal commands|The client responds only to vigorous stimulation, with SpO2 of 87%|HR decreases from 84 to 76/min|The client reports feeling relaxed','B','Responding only to vigorous stimulation, with hypoxemia, indicates the client has moved into deep sedation with respiratory compromise. Airway support, oxygen, and reversal agents (naloxone, flumazenil) may be needed.','Integrated','Adult Health'),
('Set23-RN-4','Reduction of Risk Potential','Wound healing risk factors','multiple_response','Reduction of Risk Potential • Wound healing risk factors • Select all that apply Which factors increase a client''s risk for delayed surgical wound healing? Select all that apply.','Poorly controlled diabetes|Cigarette smoking|Obesity|Protein-calorie malnutrition|Long-term corticosteroid use|Adequate hydration    ','A,B,C,D,E','Hyperglycemia, reduced tissue oxygenation from smoking, poorly vascularized adipose tissue, inadequate protein, and steroid-induced immunosuppression all impair healing.','Integrated','Adult Health'),
('Set23-RN-5','Pharmacological and Parenteral Therapies','Sacubitril-valsartan','single_best_answer','Pharmacological and Parenteral Therapies • Sacubitril-valsartan • Multiple choice A client with heart failure taking lisinopril is being switched to sacubitril-valsartan. Which instruction is most important?','"Take both medications together for the first week."|"Stop lisinopril at least 36 hours before starting sacubitril-valsartan."|"Take sacubitril-valsartan only when you feel short of breath."|"Increase your potassium intake."','B','Combining an ACE inhibitor with sacubitril-valsartan greatly increases the risk of angioedema, so a 36-hour washout is required. Potassium is monitored because the drug can raise levels.','Integrated','Pharmacology'),
('Set23-RN-6','Pharmacological and Parenteral Therapies','Adenosine','single_best_answer','Pharmacological and Parenteral Therapies • Adenosine • Multiple choice The nurse is administering adenosine for stable supraventricular tachycardia. Which technique is correct?','Infuse it slowly over 10 minutes|Give it as a rapid IV push through a port close to the heart, immediately followed by a rapid saline flush|Give it intramuscularly|Mix it in a 250-mL bag of D5W','B','Adenosine has a half-life of seconds, so it must reach the heart quickly. A brief pause or asystole on the monitor is expected. The client should be warned about transient chest discomfort and flushing.','Integrated','Pharmacology'),
('Set23-RN-7','Physiological Adaptation','Flail chest','single_best_answer','Physiological Adaptation • Flail chest • Multiple choice A client with multiple rib fractures after a car crash has a section of the chest wall that moves inward during inspiration and outward during expiration. What does the nurse suspect?','Normal breathing after trauma|Flail chest with paradoxical chest wall movement|Pleural effusion|Asthma','B','Flail chest occurs when adjacent ribs break in multiple places, creating a free-floating segment. It impairs ventilation and is often accompanied by pulmonary contusion. Pain control and ventilatory support are key.','Integrated','Adult Health'),
('Set23-RN-8','Physiological Adaptation','Subarachnoid hemorrhage','single_best_answer','Physiological Adaptation • Subarachnoid hemorrhage • Multiple choice A client arrives saying, "This is the worst headache of my life," with neck stiffness and vomiting. A subarachnoid hemorrhage from a ruptured aneurysm is confirmed. Which medication does the nurse anticipate to reduce the risk of cerebral vasospasm?','Nimodipine|Alteplase|Heparin|Aspirin    ','A','Nimodipine reduces poor outcomes from delayed cerebral ischemia caused by vasospasm. Thrombolytics, anticoagulants, and antiplatelets are contraindicated in hemorrhagic stroke.','Integrated','Adult Health'),
('Set23-RN-9','Basic Care and Comfort','Diabetic gastroparesis','single_best_answer','Basic Care and Comfort • Diabetic gastroparesis • Multiple choice A client with long-standing diabetes has early fullness, nausea, and bloating. Diabetic gastroparesis is diagnosed. Which dietary recommendation should the nurse give?','"Eat three large, high-fiber meals."|"Eat small, frequent meals that are low in fat and fiber."|"Lie down right after eating."|"Drink carbonated beverages with meals."','B','Fat and fiber slow gastric emptying. Small meals are better tolerated. Metoclopramide may be prescribed, and the nurse monitors for involuntary movements (tardive dyskinesia).','Integrated','Adult Health'),
('Set23-RN-10','Reduction of Risk Potential','Diarrhea during tube feeding','single_best_answer','Reduction of Risk Potential • Diarrhea during tube feeding • Multiple choice A client receiving continuous enteral feeding develops diarrhea. Which action should the nurse take first?','Stop the feeding permanently|Review medications for sorbitol-containing liquids and recent antibiotics, and assess for C. difficile and formula rate or tolerance issues|Give an antidiarrheal immediately|Double the free-water flushes','B','Diarrhea during tube feeding is often caused by medications (sorbitol, magnesium, antibiotics) or infection rather than the formula itself. Antidiarrheals are avoided until C. difficile is ruled out.','Integrated','Adult Health'),
('Set23-RN-11','Pharmacological and Parenteral Therapies','NSAIDs in CKD','single_best_answer','Pharmacological and Parenteral Therapies • NSAIDs in CKD • Multiple choice A client with stage 3 chronic kidney disease asks whether ibuprofen is safe for knee pain. What is the nurse''s best response?','"Ibuprofen is the safest pain reliever for you."|"Ibuprofen and other NSAIDs can reduce kidney blood flow and worsen kidney function. Ask your provider about safer options, such as acetaminophen."|"Take double doses for better relief."|"NSAIDs protect the kidneys."','B','NSAIDs inhibit prostaglandins that maintain renal perfusion and can cause acute kidney injury, hyperkalemia, and fluid retention in CKD.','Integrated','Pharmacology'),
('Set23-RN-12','Pharmacological and Parenteral Therapies','Colchicine','single_best_answer','Pharmacological and Parenteral Therapies • Colchicine • Multiple choice A client with an acute gout flare is taking colchicine. Which finding should the nurse report because it may signal toxicity?','Decreased joint pain|Severe diarrhea, nausea, and vomiting|Improved mobility|Mild fatigue    ','B','GI symptoms are early signs of colchicine toxicity. Toxicity risk increases with kidney impairment and with drugs such as clarithromycin.','Integrated','Pharmacology'),
('Set23-RN-13','Pharmacological and Parenteral Therapies','Platelet transfusion','single_best_answer','Pharmacological and Parenteral Therapies • Platelet transfusion • Multiple choice A stable, nonbleeding client receiving chemotherapy has several platelet counts. At which count is a prophylactic platelet transfusion most commonly indicated?','120,000/mm³|75,000/mm³|45,000/mm³|8,000/mm³','D','Prophylactic platelet transfusion is commonly given when counts fall below about 10,000/mm³ in stable clients. Higher thresholds apply for active bleeding or procedures.','Integrated','Pharmacology'),
('Set23-RN-14','Psychosocial Integrity','Palliative care vs hospice','single_best_answer','Psychosocial Integrity • Palliative care vs hospice • Multiple choice A client with advanced heart failure asks the difference between palliative care and hospice. Which response by the nurse is accurate?','"They are exactly the same."|"Palliative care focuses on comfort and quality of life and can be given alongside treatments at any stage. Hospice is for people with a life expectancy of about 6 months or less who choose comfort-focused care."|"Palliative care means you are giving up."|"Hospice is only for people with cancer."','B','Palliative care can begin at diagnosis alongside curative treatment. Hospice is a type of palliative care for terminal illness when curative treatment is no longer pursued.','Integrated','Mental Health'),
('Set23-RN-15','Health Promotion and Maintenance','Contact dermatitis','single_best_answer','Health Promotion and Maintenance • Contact dermatitis • Multiple choice A client with a blistering poison ivy rash asks whether it can spread to others. Which response by the nurse is accurate?','"The fluid in the blisters spreads the rash."|"The blister fluid doesn''t spread it, but the plant oil can remain on skin, clothing, and pets. Wash them to prevent new exposures."|"You need to be isolated."|"Scratching helps the rash heal."','B','Urushiol oil causes the reaction. Washing skin soon after exposure and cleaning contaminated items prevents further spread. Cool compresses and topical steroids relieve symptoms.','Integrated','Fundamentals'),
('Set23-RN-16','Health Promotion and Maintenance','Fetal position','single_best_answer','Health Promotion and Maintenance • Fetal position • Multiple choice Leopold maneuvers suggest the fetus is in a breech presentation. Where does the nurse expect to hear the fetal heart tones best?','Below the umbilicus|Above the umbilicus|At the symphysis pubis only|Heart tones cannot be heard in breech presentation    ','B','Fetal heart tones are heard best through the fetal back. In breech presentation, the fetal back and heart are higher, so tones are usually heard above the umbilicus. In vertex presentation, they are usually below.','Integrated','Fundamentals'),
('Set23-RN-17','Basic Care and Comfort','Pediatric procedural pain','single_best_answer','Basic Care and Comfort • Pediatric procedural pain • Multiple choice A 6-year-old needs an IV started in 1 hour. Which intervention does the nurse anticipate to reduce procedural pain?','Apply a topical anesthetic cream, such as lidocaine-prilocaine, to the site as prescribed and cover it|Tell the child it won''t hurt|Have several staff restrain the child firmly|Give an IM opioid injection','A','Topical anesthetics need time (about 30–60 minutes, depending on the product) to numb the skin. Distraction and a parent''s comfort also help. Honesty builds trust.','Integrated','Adult Health'),
('Set23-RN-18','Physiological Adaptation','Hemorrhagic stroke','single_best_answer','Physiological Adaptation • Hemorrhagic stroke • Multiple choice A client with a confirmed intracerebral hemorrhage takes warfarin. Which intervention does the nurse anticipate?','Continue warfarin|Rapid anticoagulation reversal, such as IV vitamin K with 4-factor prothrombin complex concentrate, and blood pressure control|IV alteplase|Aspirin to prevent another stroke','B','Reversing anticoagulation and controlling BP limit hematoma expansion. Thrombolytics and antiplatelets are contraindicated.','Integrated','Adult Health'),
('Set23-RN-19','Psychosocial Integrity','Children''s understanding of death','single_best_answer','Psychosocial Integrity • Children''s understanding of death • Multiple choice The parent of a 4-year-old whose grandparent recently died says the child keeps asking when Grandpa will come back. How should the nurse explain this?','"Your child is in denial and needs therapy."|"Preschoolers often think death is temporary or reversible. Use simple, honest words like ''died'' and explain that Grandpa''s body stopped working."|"Tell your child that Grandpa is sleeping."|"Avoid talking about it."  ','B','Preschoolers see death as temporary. Concrete, honest language is best. Euphemisms like "sleeping" can cause fear of sleep. School-age children begin to understand that death is permanent.','Integrated','Mental Health'),
('Set24-RN-1','Management of Care','Prioritization: medical unit','single_best_answer','Management of Care • Prioritization: medical unit • Multiple choice The nurse receives report on four clients. Which client should the nurse assess first?','A client with pulmonary arterial hypertension whose continuous IV epoprostenol pump is alarming "occlusion"|A client with COPD requesting a scheduled inhaler|A client with pneumonia whose temperature is 100.2°F (37.9°C)|A client with heart failure due for a daily weight','A','Epoprostenol has a half-life of minutes. Even a brief interruption can cause rebound pulmonary hypertension and cardiovascular collapse. The occlusion must be resolved immediately, and a backup line or pump is kept available.','Integrated','Management of Care'),
('Set24-RN-2','Reduction of Risk Potential','Temporary pacing','single_best_answer','Reduction of Risk Potential • Temporary pacing • Multiple choice A client has a temporary transvenous pacemaker. The monitor shows pacing spikes that are not followed by QRS complexes, and the client is lightheaded. How should the nurse interpret this?','Normal pacing function|Failure to capture|Failure to sense (undersensing)|Oversensing','B','Pacer spikes without a following depolarization indicate failure to capture. The nurse checks connections, notifies the provider, and anticipates increasing the output or repositioning the lead. Transcutaneous pacing should be available.','Integrated','Adult Health'),
('Set24-RN-3','Pharmacological and Parenteral Therapies','DOAC reversal','single_best_answer','Pharmacological and Parenteral Therapies • DOAC reversal • Multiple choice A client taking dabigatran is admitted with a life-threatening GI bleed. Which reversal agent does the nurse anticipate?','Vitamin K|Idarucizumab|Protamine sulfate|Naloxone','B','Idarucizumab specifically reverses dabigatran, a direct thrombin inhibitor. Andexanet alfa reverses factor Xa inhibitors such as apixaban and rivaroxaban. Vitamin K reverses warfarin, and protamine reverses heparin.','Integrated','Pharmacology'),
('Set24-RN-4','Safety and Infection Control','Speaking valve','single_best_answer','Safety and Infection Control • Speaking valve • Multiple choice The nurse is placing a one-way speaking valve on a client''s cuffed tracheostomy tube. Which action is essential before placing the valve?','Fully inflate the cuff|Completely deflate the cuff|Remove the inner cannula permanently|Increase the oxygen to 15 L/min    ','B','A speaking valve lets air in but not out through the tube. With the cuff inflated, exhaled air cannot pass around the tube, which can cause suffocation. The cuff must be fully deflated first.','Integrated','Safety & Infection Control'),
('Set24-RN-5','Health Promotion and Maintenance','Pneumococcal vaccination','single_best_answer','Health Promotion and Maintenance • Pneumococcal vaccination • Multiple choice Under current CDC recommendations, which adult should be offered pneumococcal vaccination at a routine visit, even without other risk factors?','A healthy 30-year-old|A healthy 52-year-old|A healthy 40-year-old|Only adults 70 and older','B','As of October 2024, the CDC recommends pneumococcal conjugate vaccination for all adults 50 and older. Younger adults with certain chronic conditions are also eligible.','Integrated','Fundamentals'),
('Set24-RN-6','Physiological Adaptation','Normal pressure hydrocephalus','single_best_answer','Physiological Adaptation • Normal pressure hydrocephalus • Multiple choice An older adult has a magnetic (shuffling) gait, urinary incontinence, and progressive memory problems. Which condition should the nurse recognize as a possible cause?','Normal pressure hydrocephalus|Bell''s palsy|Myasthenia gravis|Peripheral neuropathy only','A','The triad of gait disturbance, urinary incontinence, and dementia suggests normal pressure hydrocephalus, which may improve with a shunt. It is sometimes mistaken for Alzheimer''s or Parkinson''s disease.','Integrated','Adult Health'),
('Set24-RN-7','Health Promotion and Maintenance','Intermittent self-catheterization','single_best_answer','Health Promotion and Maintenance • Intermittent self-catheterization • Multiple choice A client with a neurogenic bladder is learning intermittent self-catheterization at home. Which instruction is correct?','"Use sterile technique and a new catheter every time, even at home."|"Clean technique is generally used at home. Wash your hands, catheterize on a regular schedule, and follow instructions for catheter care or single-use catheters."|"Catheterize only when you feel you have to urinate."|"Limit fluids to 500 mL a day to avoid catheterizing."','B','Clean intermittent catheterization at home is safe and reduces infection compared with indwelling catheters. A regular schedule prevents overdistention. Adequate fluids reduce UTI risk.','Integrated','Fundamentals'),
('Set24-RN-8','Reduction of Risk Potential','Transsphenoidal surgery','single_best_answer','Reduction of Risk Potential • Transsphenoidal surgery • Multiple choice A client is recovering from transsphenoidal pituitary surgery for acromegaly. Which instruction should the nurse include?','"Blow your nose to clear drainage."|"Avoid coughing, sneezing, blowing your nose, and bending over, and report clear, watery drainage from your nose."|"Brush your teeth vigorously right away."|"Drink through a straw."    ','B','These activities increase pressure on the surgical site and can cause a CSF leak. Clear nasal drainage may be CSF. Toothbrushing near the incision is avoided until allowed, and urine output is monitored for diabetes insipidus.','Integrated','Adult Health'),
('Set24-RN-9','Reduction of Risk Potential','Continuous glucose monitoring','single_best_answer','Reduction of Risk Potential • Continuous glucose monitoring • Multiple choice A client using a continuous glucose monitor (CGM) feels shaky and sweaty, but the CGM reads 132 mg/dL. What should the nurse advise?','"Trust the monitor and ignore your symptoms."|"Check a fingerstick glucose to confirm, because symptoms that don''t match the reading should be verified."|"Give insulin to bring it down."|"Remove the sensor permanently."','B','CGMs measure interstitial glucose, which lags behind blood glucose during rapid changes. When symptoms don''t match, a fingerstick confirms the value before treatment decisions.','Integrated','Adult Health'),
('Set24-RN-10','Physiological Adaptation','Toxic megacolon','single_best_answer','Physiological Adaptation • Toxic megacolon • Multiple choice A client with a severe ulcerative colitis flare develops a distended abdomen, fever, HR 128/min, and fewer stools. What does the nurse suspect?','Improvement of colitis|Toxic megacolon|Constipation from diet|Gastroesophageal reflux','B','Toxic megacolon is life-threatening colonic dilation with systemic toxicity and risk of perforation. Antidiarrheals, opioids, and anticholinergics can precipitate it and are avoided. The client is kept NPO, decompressed, and evaluated surgically.','Integrated','Adult Health'),
('Set24-RN-11','Reduction of Risk Potential','Peritoneal dialysis metabolic effects','single_best_answer','Reduction of Risk Potential • Peritoneal dialysis metabolic effects • Multiple choice A client on peritoneal dialysis has gained weight and has rising blood glucose levels. What is the most likely cause?','Absorption of dextrose from the dialysate|Loss of protein in the dialysate|Hyperkalemia|Too little fluid intake','A','The dextrose in peritoneal dialysate is absorbed, adding calories and raising glucose, which can lead to weight gain and hyperglycemia. Protein loss is also common, so a high-protein diet is recommended.','Integrated','Adult Health'),
('Set24-RN-12','Physiological Adaptation','Thrombotic thrombocytopenic purpura','single_best_answer','Physiological Adaptation • Thrombotic thrombocytopenic purpura • Multiple choice A client is diagnosed with thrombotic thrombocytopenic purpura (TTP). Which treatment does the nurse anticipate?','Platelet transfusion as first-line treatment|Urgent plasma exchange|Heparin infusion|Oral iron    ','B','TTP causes microvascular clots with thrombocytopenia and hemolytic anemia. Plasma exchange removes the antibodies against ADAMTS13 and replaces the enzyme. Platelet transfusion is generally avoided because it may worsen clotting.','Integrated','Adult Health'),
('Set24-RN-13','Physiological Adaptation','Multiple myeloma','single_best_answer','Physiological Adaptation • Multiple myeloma • Multiple choice A client with multiple myeloma reports bone pain and constipation. The calcium level is 12.8 mg/dL and creatinine is rising. Which intervention should the nurse include?','Restrict fluids|Encourage fluids of about 2–3 L/day unless restricted, implement fall precautions, and monitor kidney function|Encourage bed rest|Increase dietary calcium','B','Myeloma causes bone destruction, hypercalcemia, and kidney injury. Hydration protects the kidneys, and fall precautions reduce the risk of pathologic fractures. Weight-bearing activity is encouraged as tolerated.','Integrated','Adult Health'),
('Set24-RN-14','Physiological Adaptation','Systemic sclerosis','single_best_answer','Physiological Adaptation • Systemic sclerosis • Multiple choice A client with systemic sclerosis (scleroderma) has a sudden rise in BP to 188/110 mm Hg, headache, and decreasing urine output. What does the nurse suspect?','Scleroderma renal crisis|Normal disease progression|Raynaud''s phenomenon|Dehydration','A','Scleroderma renal crisis presents with sudden hypertension and acute kidney injury. ACE inhibitors are the cornerstone of treatment. Scleroderma also causes skin thickening, Raynaud''s phenomenon, and esophageal dysmotility.','Integrated','Adult Health'),
('Set24-RN-15','Psychosocial Integrity','Functional neurological symptom disorder','single_best_answer','Psychosocial Integrity • Functional neurological symptom disorder • Multiple choice After witnessing a car crash, a client develops sudden paralysis of the legs. Neurological workup shows no physical cause, and the client seems unconcerned about the paralysis. Which approach should the nurse use?','Tell the client the paralysis is fake|Acknowledge the symptoms as real to the client, avoid focusing on the paralysis, and encourage expression of feelings about the event|Force the client to walk|Ignore the client','B','In functional neurological (conversion) disorder, psychological stress produces real neurological symptoms. A lack of concern (la belle indifférence) may be present. Supportive care focuses on stress and coping, and physical therapy may help.','Integrated','Mental Health'),
('Set24-RN-16','Pharmacological and Parenteral Therapies','Antidepressant discontinuation','single_best_answer','Pharmacological and Parenteral Therapies • Antidepressant discontinuation • Multiple choice A client stopped paroxetine abruptly 3 days ago and now reports dizziness, "electric shock" sensations, irritability, and flu-like symptoms. What does the nurse suspect?','Serotonin syndrome|Antidepressant discontinuation syndrome|A new viral infection only|Lithium toxicity    ','B','Abruptly stopping SSRIs, especially short half-life agents like paroxetine, can cause discontinuation syndrome. Tapering prevents it. Clients are taught not to stop antidepressants suddenly.','Integrated','Pharmacology'),
('Set24-RN-17','Physiological Adaptation','Postpartum preeclampsia','single_best_answer','Physiological Adaptation • Postpartum preeclampsia • Multiple choice A client who gave birth 8 days ago calls reporting a severe headache and blurred vision. Her pregnancy was uncomplicated. What should the nurse advise?','"Take acetaminophen and rest."|"Come in for evaluation immediately. Preeclampsia can develop after birth, even without problems during pregnancy."|"This is normal after having a baby."|"Wait until your 6-week checkup."','B','Postpartum preeclampsia can occur up to about 6 weeks after delivery and can progress to eclampsia or stroke. A severe headache and visual changes require urgent BP evaluation.','Integrated','Adult Health'),
('Set24-RN-18','Physiological Adaptation','Chorioamnionitis','single_best_answer','Physiological Adaptation • Chorioamnionitis • Multiple choice A laboring client with membranes ruptured for 22 hours has a temperature of 101.4°F (38.6°C), uterine tenderness, foul-smelling amniotic fluid, and a fetal heart rate baseline of 175/min. What does the nurse suspect?','Normal labor|Chorioamnionitis (intra-amniotic infection)|Placenta previa|Supine hypotension','B','Maternal fever with fetal tachycardia, uterine tenderness, and foul fluid indicate intra-amniotic infection. Prolonged rupture of membranes is a major risk factor. Treatment includes antibiotics, and the newborn is evaluated for sepsis.','Integrated','Adult Health'),
('Set24-RN-19','Safety and Infection Control','Button battery ingestion','single_best_answer','Safety and Infection Control • Button battery ingestion • Multiple choice A parent calls to report that a 2-year-old may have swallowed a button battery 20 minutes ago. The child is breathing normally. What should the nurse advise?','"Watch for it to pass in the stool over the next few days."|"Go to the emergency department immediately. A button battery can cause severe burns in the esophagus within hours."|"Make your child vomit."|"Give your child a large meal to push it through."  ','B','Button batteries lodged in the esophagus can cause serious injury within 2 hours and require urgent removal. Vomiting is not induced. Poison control may advise giving honey to children over 1 year while en route to reduce injury.','Integrated','Safety & Infection Control'),
('Set25-RN-1','Management of Care','Prioritization: infusion center','single_best_answer','Management of Care • Prioritization: infusion center • Multiple choice The nurse in an outpatient infusion center is caring for four clients. Which client should the nurse assess first?','A client 15 minutes into a first rituximab infusion who reports throat tightness, with wheezing and BP 84/50 mm Hg|A client receiving IV iron sucrose who reports a metallic taste|A client waiting for a scheduled port flush|A client receiving IV hydration who asks for a blanket','A','Throat tightness, wheezing, and hypotension indicate a severe infusion reaction or anaphylaxis requiring immediate action (stop the infusion and follow the emergency protocol). A metallic taste with IV iron is a minor side effect.','Integrated','Management of Care'),
('Set25-RN-2','Pharmacological and Parenteral Therapies','Nitroprusside','single_best_answer','Pharmacological and Parenteral Therapies • Nitroprusside • Multiple choice A client is receiving a nitroprusside infusion for hypertensive emergency. Which nursing action is correct?','Expose the infusion to light to activate it|Protect the infusion from light, monitor BP continuously, and watch for signs of cyanide or thiocyanate toxicity with prolonged use|Give it as an IV push|Stop it abruptly once BP is normal','B','Nitroprusside degrades in light, acts within seconds, and requires continuous arterial BP monitoring. Prolonged or high-dose use can cause cyanide toxicity (metabolic acidosis, confusion), especially with kidney or liver impairment.','Integrated','Pharmacology'),
('Set25-RN-3','Pharmacological and Parenteral Therapies','Beta blockers and hypoglycemia','single_best_answer','Pharmacological and Parenteral Therapies • Beta blockers and hypoglycemia • Multiple choice A client with type 1 diabetes is started on metoprolol. Which teaching point is most important?','"Metoprolol will raise your blood sugar dangerously."|"Metoprolol can hide some warning signs of low blood sugar, like a racing heart and shakiness. Sweating may still occur, so check your glucose more often."|"You can stop checking your blood sugar."|"Metoprolol prevents low blood sugar."','B','Beta blockers blunt adrenergic signs of hypoglycemia such as tachycardia and tremor, delaying recognition. Sweating is cholinergically mediated and may persist. More frequent monitoring is advised.','Integrated','Pharmacology'),
('Set25-RN-4','Pharmacological and Parenteral Therapies','Montelukast','single_best_answer','Pharmacological and Parenteral Therapies • Montelukast • Multiple choice A teenager with asthma is prescribed montelukast. Which instruction should the nurse include?','"Use it as a rescue inhaler during an attack."|"Report any mood changes, unusual dreams, agitation, or thoughts of self-harm right away."|"Take it only on days you have symptoms."|"It replaces all your other asthma medications."    ','B','Montelukast carries an FDA boxed warning for serious neuropsychiatric events. It is a daily controller medication, not a rescue drug.','Integrated','Pharmacology'),
('Set25-RN-5','Pharmacological and Parenteral Therapies','Varenicline','single_best_answer','Pharmacological and Parenteral Therapies • Varenicline • Multiple choice A client is starting varenicline to quit smoking. Which instruction is correct?','"Stop smoking the day before you start the medication."|"Set a quit date about 1 week after starting, take it after eating with a full glass of water, and report mood or behavior changes."|"Take it on an empty stomach."|"You can continue smoking as much as you like while taking it."','B','Varenicline is started 1 week before the quit date (or with a flexible quit approach). Taking it with food reduces nausea. Neuropsychiatric effects, although less common than once thought, should be reported.','Integrated','Pharmacology'),
('Set25-RN-6','Reduction of Risk Potential','Post-dural puncture headache','single_best_answer','Reduction of Risk Potential • Post-dural puncture headache • Multiple choice A client who had spinal anesthesia for surgery yesterday reports a severe headache that worsens when sitting up and improves when lying flat. Which treatment may be offered if conservative measures fail?','Emergency craniotomy|Epidural blood patch|Increasing activity to walk it off|Restricting fluids','B','A positional headache after dural puncture results from CSF leakage. Initial care includes hydration, caffeine, and analgesics. An epidural blood patch seals the leak if the headache persists.','Integrated','Adult Health'),
('Set25-RN-7','Reduction of Risk Potential','Steroid-induced hyperglycemia','single_best_answer','Reduction of Risk Potential • Steroid-induced hyperglycemia • Multiple choice A client with type 2 diabetes is started on high-dose prednisone for a COPD exacerbation. What does the nurse anticipate?','Lower blood glucose levels|Higher blood glucose levels, especially in the afternoon and evening, requiring closer monitoring and possible insulin adjustment|No change in glucose|Stopping all diabetes medications','B','Glucocorticoids increase insulin resistance and hepatic glucose production. Morning prednisone typically raises glucose later in the day.','Integrated','Adult Health'),
('Set25-RN-8','Reduction of Risk Potential','Esophageal perforation','single_best_answer','Reduction of Risk Potential • Esophageal perforation • Multiple choice Two hours after an upper endoscopy with esophageal dilation, the client reports severe chest and neck pain, has a fever, and the nurse feels crackling under the skin of the neck. What does the nurse suspect?','Expected sore throat|Esophageal perforation|Gastroesophageal reflux|Allergic reaction to sedation    ','B','Chest or neck pain, fever, and subcutaneous emphysema after endoscopy suggest perforation, a surgical emergency. The client is kept NPO and the provider notified immediately.','Integrated','Adult Health'),
('Set25-RN-9','Reduction of Risk Potential','Urine specific gravity','single_best_answer','Reduction of Risk Potential • Urine specific gravity • Multiple choice A client''s urine specific gravity is 1.035. How should the nurse interpret this finding?','Dilute urine suggesting overhydration|Concentrated urine suggesting dehydration or fluid volume deficit|A normal finding in all situations|Evidence of diabetes insipidus','B','Normal urine specific gravity is about 1.005–1.030. A high value indicates concentrated urine, as in dehydration or SIADH. A low value suggests overhydration or diabetes insipidus.','Integrated','Adult Health'),
('Set25-RN-10','Health Promotion and Maintenance','Bone density results','single_best_answer','Health Promotion and Maintenance • Bone density results • Multiple choice A postmenopausal client''s DEXA scan shows a T-score of −2.7 at the hip. How should the nurse interpret this result?','Normal bone density|Osteopenia|Osteoporosis|Osteoarthritis','C','A T-score of −2.5 or lower indicates osteoporosis. Scores between −1.0 and −2.5 indicate low bone mass (osteopenia), and −1.0 or higher is normal.','Integrated','Fundamentals'),
('Set25-RN-11','Physiological Adaptation','Hodgkin lymphoma','single_best_answer','Physiological Adaptation • Hodgkin lymphoma • Multiple choice A young adult has a painless, enlarged lymph node in the neck. Which additional findings would most support Hodgkin lymphoma?','Weight gain and cold intolerance|Unexplained fevers, drenching night sweats, and unintentional weight loss|Joint pain and a butterfly rash|Bloody diarrhea','B','These "B symptoms" are associated with lymphoma and affect staging and prognosis. Diagnosis is confirmed by lymph node biopsy.','Integrated','Adult Health'),
('Set25-RN-12','Pharmacological and Parenteral Therapies','Immune checkpoint inhibitors','single_best_answer','Pharmacological and Parenteral Therapies • Immune checkpoint inhibitors • Multiple choice A client receiving pembrolizumab for melanoma reports six loose stools a day and abdominal cramping. What should the nurse do?','Recommend an over-the-counter antidiarrheal and continue|Report the symptoms promptly, since this may be immune-related colitis that often requires corticosteroids|Reassure the client that this is expected and harmless|Stop all fluids    ','B','Checkpoint inhibitors can cause immune-related adverse events affecting the colon, liver, lungs, and endocrine glands. Early recognition and treatment prevent serious complications.','Integrated','Pharmacology'),
('Set25-RN-13','Pharmacological and Parenteral Therapies','Tetracyclines','single_best_answer','Pharmacological and Parenteral Therapies • Tetracyclines • Multiple choice Which instruction should the nurse give a client prescribed doxycycline?','"Take it with a glass of milk."|"Take it with a full glass of water, stay upright for 30 minutes, avoid taking it with dairy, antacids, or iron, and use sun protection."|"Lie down right after taking it."|"It is safe for children under 8 in all cases."','B','Doxycycline can cause esophageal ulceration and photosensitivity. Calcium, magnesium, and iron reduce absorption. Tetracyclines are generally avoided in young children and pregnancy because of tooth discoloration, although short courses of doxycycline are acceptable for certain infections.','Integrated','Pharmacology'),
('Set25-RN-14','Pharmacological and Parenteral Therapies','Tardive dyskinesia','single_best_answer','Pharmacological and Parenteral Therapies • Tardive dyskinesia • Multiple choice A client taking an antipsychotic for many years has repetitive lip smacking and tongue thrusting. Which action should the nurse take?','Increase the antipsychotic dose|Perform and document an Abnormal Involuntary Movement Scale (AIMS) assessment and report the findings|Give benztropine and expect the movements to resolve|Ignore the movements','B','These are signs of tardive dyskinesia. AIMS monitoring detects it early. Treatment may include changing the antipsychotic or adding a VMAT2 inhibitor. Anticholinergics generally do not help and may worsen TD.','Integrated','Pharmacology'),
('Set25-RN-15','Pharmacological and Parenteral Therapies','Antipsychotics in dementia','single_best_answer','Pharmacological and Parenteral Therapies • Antipsychotics in dementia • Multiple choice An older adult with dementia and agitation is prescribed quetiapine. Which information should guide the nurse''s care?','Antipsychotics are the first-line treatment for all dementia behaviors|Antipsychotics carry a boxed warning for increased mortality in older adults with dementia, so nonpharmacological approaches are tried first and the medication''s use is closely monitored|There are no risks in older adults|The dose should be doubled if agitation continues','B','Antipsychotics increase the risk of death, stroke, and falls in older adults with dementia. Identifying triggers, meeting needs, and environmental approaches come first.','Integrated','Pharmacology'),
('Set25-RN-16','Health Promotion and Maintenance','Newborn scalp swelling','single_best_answer','Health Promotion and Maintenance • Newborn scalp swelling • Multiple choice After a vacuum-assisted birth, a newborn has a firm swelling on one side of the head that does not cross the suture line. What should the nurse document and monitor for?','Caput succedaneum; no follow-up needed|Cephalohematoma; monitor for jaundice as the collected blood breaks down|Normal molding|Hydrocephalus    ','B','A cephalohematoma is bleeding under the periosteum, so it does not cross sutures. It resolves over weeks, and red blood cell breakdown can increase bilirubin. Caput succedaneum is scalp edema that crosses sutures and resolves in days.','Integrated','Fundamentals'),
('Set25-RN-17','Reduction of Risk Potential','Biophysical profile','single_best_answer','Reduction of Risk Potential • Biophysical profile • Multiple choice A client at 38 weeks'' gestation has a biophysical profile score of 8 out of 10 with normal amniotic fluid. How should the nurse interpret this?','Fetal distress requiring immediate delivery|A reassuring result|An inconclusive test that must be repeated immediately|A sign of preterm labor','B','The BPP scores fetal breathing, movement, tone, amniotic fluid volume, and a nonstress test, each worth 0 or 2. A score of 8–10 with normal fluid is reassuring.','Integrated','Adult Health'),
('Set25-RN-18','Physiological Adaptation','Hemolytic uremic syndrome','single_best_answer','Physiological Adaptation • Hemolytic uremic syndrome • Multiple choice A 4-year-old who had bloody diarrhea a week ago after a family barbecue is now pale, has petechiae, and has had very little urine output. What does the nurse suspect?','Dehydration only|Hemolytic uremic syndrome|Kawasaki disease|Iron deficiency anemia','B','HUS, often after Shiga toxin-producing E. coli infection, causes hemolytic anemia, thrombocytopenia, and acute kidney injury. Antibiotics and antidiarrheals are generally avoided, and supportive care or dialysis may be needed.','Integrated','Adult Health'),
('Set25-RN-19','Physiological Adaptation','Slipped capital femoral epiphysis','single_best_answer','Physiological Adaptation • Slipped capital femoral epiphysis • Multiple choice A 12-year-old with obesity has a limp and reports pain in the knee and thigh for 3 weeks. Slipped capital femoral epiphysis is suspected. Which action is most important?','Encourage the child to keep walking and playing sports|Keep the child non-weight-bearing on the affected leg and prepare for surgical evaluation|Apply heat to the knee|Reassure the family that it''s growing pains  ','B','In SCFE, the femoral head slips from the femoral neck at the growth plate. Pain may be referred to the knee. Weight-bearing can worsen the slip, and surgical pinning is the usual treatment.','Integrated','Adult Health'),
('Set26-RN-1','Management of Care','Prioritization','single_best_answer','Management of Care • Prioritization • Multiple choice The nurse receives messages about four clients. Which client should the nurse address first?','A client with Addison''s disease who has been vomiting since morning and cannot keep down the oral hydrocortisone|A client with hypothyroidism asking whether to take levothyroxine before breakfast|A client with type 2 diabetes whose fasting glucose was 142 mg/dL|A client with gout asking about foods to avoid','A','A client with adrenal insufficiency who cannot absorb oral steroids is at risk for adrenal crisis and needs parenteral hydrocortisone and evaluation. The other concerns are routine.','Integrated','Management of Care'),
('Set26-RN-2','Reduction of Risk Potential','Arterial line','single_best_answer','Reduction of Risk Potential • Arterial line • Multiple choice The nurse is setting up an arterial line pressure monitoring system. Where should the transducer be leveled?','At the level of the client''s umbilicus|At the phlebostatic axis (fourth intercostal space, midaxillary line)|At the level of the client''s knee|Wherever it is convenient','B','The phlebostatic axis approximates the level of the right atrium. A transducer that is too low gives falsely high readings, and one that is too high gives falsely low readings. The system is re-zeroed and releveled when the client''s position changes.','Integrated','Adult Health'),
('Set26-RN-3','Safety and Infection Control','Implanted port access','single_best_answer','Safety and Infection Control • Implanted port access • Multiple choice The nurse is accessing a client''s implanted venous port. Which needle should the nurse use?','A standard hypodermic needle|A noncoring (Huber) needle|A butterfly needle used for peripheral blood draws|An IV catheter','B','Noncoring needles prevent damage to the port''s silicone septum. The nurse uses sterile technique, confirms blood return before use, and flushes per policy.','Integrated','Safety & Infection Control'),
('Set26-RN-4','Reduction of Risk Potential','Endotracheal tube placement','single_best_answer','Reduction of Risk Potential • Endotracheal tube placement • Multiple choice Immediately after intubation, which finding best supports correct endotracheal tube placement while awaiting a chest x-ray?','The client''s color improves|End-tidal CO2 detection with bilateral breath sounds and no sounds over the epigastrium|The tube is taped securely|The client stops coughing    ','B','Waveform capnography or a colorimetric CO2 detector confirms tracheal placement. Equal bilateral breath sounds help rule out mainstem intubation. A chest x-ray confirms final position.','Integrated','Adult Health'),
('Set26-RN-5','Pharmacological and Parenteral Therapies','Mannitol','single_best_answer','Pharmacological and Parenteral Therapies • Mannitol • Multiple choice A client with increased intracranial pressure is receiving IV mannitol. Which action by the nurse is correct?','Refrigerate the solution before use|Use an in-line filter, inspect for crystals, and monitor urine output and serum osmolality|Give it as a rapid IV push without a filter|Restrict urine output measurement','B','Mannitol can crystallize and must be filtered. As an osmotic diuretic, it causes marked diuresis and can lead to dehydration, electrolyte imbalance, and kidney injury, so output and osmolality are monitored.','Integrated','Pharmacology'),
('Set26-RN-6','Pharmacological and Parenteral Therapies','Cholinesterase inhibitors','single_best_answer','Pharmacological and Parenteral Therapies • Cholinesterase inhibitors • Multiple choice A client with Alzheimer''s disease has started donepezil. Which finding should the nurse report?','Improved attention|Heart rate of 48/min with dizziness|Mild nausea during the first week|Sleeping well','B','Cholinesterase inhibitors increase vagal tone and can cause bradycardia and syncope. GI upset is common early. Donepezil is often taken at bedtime.','Integrated','Pharmacology'),
('Set26-RN-7','Reduction of Risk Potential','Thyroid function tests','single_best_answer','Reduction of Risk Potential • Thyroid function tests • Multiple choice A client''s lab results show a low TSH and elevated free T4. How should the nurse interpret these results?','Primary hypothyroidism|Hyperthyroidism|Normal thyroid function|Hypoparathyroidism','B','Excess thyroid hormone suppresses pituitary TSH production. In primary hypothyroidism, TSH is high and free T4 is low.','Integrated','Adult Health'),
('Set26-RN-8','Health Promotion and Maintenance','Prediabetes','single_best_answer','Health Promotion and Maintenance • Prediabetes • Multiple choice A client''s hemoglobin A1C is 6.0%. Which response by the nurse is most accurate?','"This is normal."|"This is in the prediabetes range. Lifestyle changes such as modest weight loss and regular activity can lower your risk of diabetes."|"You have type 2 diabetes and need insulin."|"This test isn''t useful."','B','An A1C of 5.7–6.4% indicates prediabetes, and 6.5% or higher indicates diabetes. Losing about 5–7% of body weight and exercising about 150 minutes per week significantly reduce progression.','Integrated','Fundamentals'),
('Set26-RN-9','Health Promotion and Maintenance','Colorectal cancer warning signs','single_best_answer','Health Promotion and Maintenance • Colorectal cancer warning signs • Multiple choice Which symptom reported by a 60-year-old client is most important for the nurse to refer for evaluation for colorectal cancer?','Occasional gas after eating beans|A change in bowel habits with narrow, pencil-thin stools and blood in the stool|One day of constipation after travel|Mild heartburn    ','B','Persistent changes in bowel habits, stool caliber, rectal bleeding, unexplained weight loss, and iron deficiency anemia are warning signs that require prompt evaluation.','Integrated','Fundamentals'),
('Set26-RN-10','Reduction of Risk Potential','Dialysis access maturation','single_best_answer','Reduction of Risk Potential • Dialysis access maturation • Multiple choice A client who will need hemodialysis asks why an arteriovenous fistula is created months before dialysis begins. What is the nurse''s best response?','"A fistula can be used the same day it is created."|"A fistula usually needs several weeks to months to mature, so the vein becomes strong enough for repeated needle access."|"It''s done early for insurance reasons."|"Fistulas never need time to heal."','B','Fistulas require maturation but have lower infection and clotting rates than grafts or catheters. Hand exercises, such as squeezing a ball, may be encouraged to help maturation.','Integrated','Adult Health'),
('Set26-RN-11','Basic Care and Comfort','Residual limb wrapping','single_best_answer','Basic Care and Comfort • Residual limb wrapping • Multiple choice The nurse is teaching a client how to wrap a below-the-knee residual limb with an elastic bandage. Which technique is correct?','Wrap in circular turns tightest at the top of the limb|Use a figure-eight pattern, applying more pressure distally and decreasing pressure proximally|Wrap loosely once a week|Wrap from the top of the thigh down to the end of the limb','B','Figure-eight wrapping with graded pressure (tighter at the end) reduces edema and shapes the limb for a prosthesis. Circular turns can create a tourniquet effect. Rewrapping is done several times daily.','Integrated','Adult Health'),
('Set26-RN-12','Pharmacological and Parenteral Therapies','Blood compatibility','single_best_answer','Pharmacological and Parenteral Therapies • Blood compatibility • Multiple choice A trauma client with unknown blood type needs an emergency transfusion of packed red blood cells before crossmatching is complete. Which blood type is most appropriate, especially for a female of childbearing potential?','AB positive|O negative|A positive|B negative','B','O-negative red cells lack A, B, and Rh(D) antigens, so they are the universal donor type for emergencies. Rh-negative blood is especially important for females of childbearing potential to prevent Rh sensitization. AB plasma is the universal plasma type.','Integrated','Pharmacology'),
('Set26-RN-13','Reduction of Risk Potential','Chemotherapy nadir','single_best_answer','Reduction of Risk Potential • Chemotherapy nadir • Multiple choice A client received cyclophosphamide 9 days ago. Why is the nurse especially watchful for signs of infection now?','The drug is no longer active|The white blood cell nadir usually occurs about 7–14 days after many chemotherapy drugs|Infection risk is highest on the day of treatment only|Chemotherapy increases white blood cells    ','B','The nadir is the lowest point of blood counts after chemotherapy, typically 7–14 days. Neutropenic precautions and fever teaching are emphasized during this time.','Integrated','Adult Health'),
('Set26-RN-14','Physiological Adaptation','Benzodiazepine withdrawal','single_best_answer','Physiological Adaptation • Benzodiazepine withdrawal • Multiple choice A client who has taken alprazolam daily for years stopped it abruptly 2 days ago. The client is anxious, tremulous, and sweating. Which complication is the nurse most concerned about?','Hypoglycemia|Seizures|Constipation|Hypothermia','B','Abrupt benzodiazepine withdrawal can cause seizures and delirium. Benzodiazepines are tapered gradually, and seizure precautions are initiated.','Integrated','Adult Health'),
('Set26-RN-15','Management of Care','Involuntary admission','single_best_answer','Management of Care • Involuntary admission • Multiple choice Which situation typically meets criteria for emergency involuntary psychiatric admission in most states?','A client who disagrees with the treatment plan|A client with a mental illness who poses an imminent danger to self or others, or is unable to meet basic needs|A client who refuses to take vitamins|A client who wants a second opinion','B','Involuntary admission requires specific legal criteria, usually imminent danger or grave disability. Clients keep certain rights, including legal representation and humane treatment.','Integrated','Management of Care'),
('Set26-RN-16','Physiological Adaptation','Neonatal respiratory distress syndrome','single_best_answer','Physiological Adaptation • Neonatal respiratory distress syndrome • Multiple choice A newborn born at 29 weeks'' gestation has grunting, nasal flaring, retractions, and increasing oxygen needs. Which treatment does the nurse anticipate?','Oral feedings every 2 hours|Surfactant administration and respiratory support such as CPAP|Routine phototherapy only|Placing the infant in an open crib','B','Preterm infants lack sufficient surfactant, which causes alveolar collapse. Exogenous surfactant and positive-pressure support improve oxygenation. Antenatal steroids reduce the risk.','Integrated','Adult Health'),
('Set26-RN-17','Pharmacological and Parenteral Therapies','Oxytocin side effects','single_best_answer','Pharmacological and Parenteral Therapies • Oxytocin side effects • Multiple choice A client has received high-dose oxytocin for many hours with large volumes of hypotonic IV fluid. She now reports headache and nausea and appears confused. Which lab result should the nurse check first?','Serum sodium|Serum calcium|Hemoglobin A1C|Serum lipase    ','A','Oxytocin has an antidiuretic effect. Prolonged infusion with hypotonic fluids can cause water intoxication and hyponatremia, leading to headache, confusion, and seizures.','Integrated','Pharmacology'),
('Set26-RN-18','Physiological Adaptation','Legg-Calvé-Perthes disease','single_best_answer','Physiological Adaptation • Legg-Calvé-Perthes disease • Multiple choice A 6-year-old boy has a painless or mildly painful limp that has developed over several weeks. X-rays show avascular necrosis of the femoral head. Which information should the nurse include for the family?','"Your child should continue high-impact sports."|"Treatment focuses on protecting the hip, such as limiting weight-bearing or high-impact activities, with bracing or surgery in some cases, while the bone heals."|"This condition resolves in a week."|"It is caused by an infection."','B','Legg-Calvé-Perthes disease is self-limiting but can take years to resolve. Protecting the femoral head from stress while it revascularizes helps preserve its shape.','Integrated','Adult Health'),
('Set26-RN-19','Pharmacological and Parenteral Therapies','Pediatric otitis media','single_best_answer','Pharmacological and Parenteral Therapies • Pediatric otitis media • Multiple choice A 3-year-old is prescribed amoxicillin for acute otitis media. Which instruction should the nurse include?','"Stop the antibiotic once the ear pain goes away."|"Give the full course as prescribed, and call if your child isn''t improving within 48–72 hours or develops a rash."|"Give aspirin for the ear pain."|"Put the leftover antibiotic in the ear."  ','B','Completing therapy prevents recurrence and resistance. Lack of improvement may require a different antibiotic. Rash may indicate allergy. Acetaminophen or ibuprofen (not aspirin) is used for pain.','Integrated','Pharmacology'),
('Set27-RN-1','Management of Care','Prioritization: emergency department','single_best_answer','Management of Care • Prioritization: emergency department • Multiple choice The emergency department nurse is triaging four clients. Which client should the nurse see first?','A client 7 weeks pregnant with sudden one-sided pelvic pain, right shoulder pain, and dizziness|A client 10 weeks pregnant with mild nausea|A client 30 weeks pregnant requesting a work note|A client 12 weeks pregnant with light spotting and no pain','A','One-sided pelvic pain with referred shoulder pain (from diaphragmatic irritation by blood) and dizziness suggests a ruptured ectopic pregnancy with intraperitoneal hemorrhage, a surgical emergency.','Integrated','Management of Care'),
('Set27-RN-2','Physiological Adaptation','Complete heart block','single_best_answer','Physiological Adaptation • Complete heart block • Multiple choice A client''s monitor shows P waves and QRS complexes occurring independently, with a ventricular rate of 34/min. The client is dizzy and has BP 78/46 mm Hg. Which intervention does the nurse anticipate?','Synchronized cardioversion|Transcutaneous pacing (atropine may be tried but is often ineffective)|Adenosine rapid IV push|Observation only','B','Third-degree AV block with symptoms requires pacing. Transcutaneous pacing is used until a transvenous or permanent pacemaker can be placed. Adenosine would worsen the block.','Integrated','Adult Health'),
('Set27-RN-3','Physiological Adaptation','Adult CPR quality','single_best_answer','Physiological Adaptation • Adult CPR quality • Multiple choice The nurse is performing chest compressions on an adult in cardiac arrest. Which technique reflects high-quality CPR?','Compress at 60–80 per minute, about 1 inch deep|Compress at 100–120 per minute, at least 2 inches (5 cm) but no more than 2.4 inches deep, allowing full chest recoil|Lean on the chest between compressions|Pause compressions every 30 seconds to check a pulse','B','High-quality CPR includes the correct rate and depth, full recoil, minimal interruptions, and avoiding excessive ventilation. Compressors switch about every 2 minutes.','Integrated','Adult Health'),
('Set27-RN-4','Reduction of Risk Potential','Noninvasive ventilation','single_best_answer','Reduction of Risk Potential • Noninvasive ventilation • Multiple choice For which client should the nurse question a prescription for BiPAP (noninvasive positive-pressure ventilation)?','A client with a COPD exacerbation who is alert with a rising PaCO2|A client who is vomiting repeatedly and difficult to arouse|A client with acute cardiogenic pulmonary edema who is alert|A client with obstructive sleep apnea at night    ','B','BiPAP requires a client who can protect the airway. Vomiting and decreased consciousness increase aspiration risk, and intubation is usually needed instead.','Integrated','Adult Health'),
('Set27-RN-5','Reduction of Risk Potential','Cerebral perfusion pressure','single_best_answer','Reduction of Risk Potential • Cerebral perfusion pressure • Multiple choice A client with a head injury has a MAP of 78 mm Hg and an ICP of 26 mm Hg. What is the cerebral perfusion pressure, and how should the nurse interpret it?','104 mm Hg, which is high|52 mm Hg, which is below the usual goal and risks cerebral ischemia|26 mm Hg, which is normal|78 mm Hg, which is ideal','B','CPP = MAP − ICP = 78 − 26 = 52 mm Hg. A CPP of at least about 60 mm Hg is generally targeted in adults, and ICP above about 20–22 mm Hg is elevated.','Integrated','Adult Health'),
('Set27-RN-6','Pharmacological and Parenteral Therapies','Thiazolidinediones','single_best_answer','Pharmacological and Parenteral Therapies • Thiazolidinediones • Multiple choice A client with type 2 diabetes and heart failure is prescribed pioglitazone. What should the nurse do?','Administer it and monitor glucose only|Question the prescription, because pioglitazone causes fluid retention and can worsen heart failure|Give it with a potassium supplement|Double the dose','B','Thiazolidinediones cause fluid retention and carry a boxed warning for heart failure. They are contraindicated in moderate to severe heart failure.','Integrated','Pharmacology'),
('Set27-RN-7','Physiological Adaptation','Bariatric surgery complications','single_best_answer','Physiological Adaptation • Bariatric surgery complications • Multiple choice On postoperative day 1 after a gastric bypass, which finding is the most important early sign of an anastomotic leak?','Incisional pain rated 4/10|Persistent heart rate above 120/min, new anxiety, and increasing abdominal or shoulder pain|Mild nausea after sips of water|Low-grade temperature of 99.3°F (37.4°C)','B','Unexplained sustained tachycardia is often the earliest sign of an anastomotic leak, before fever or peritoneal signs. Prompt surgical evaluation is needed.','Integrated','Adult Health'),
('Set27-RN-8','Physiological Adaptation','Spontaneous bacterial peritonitis','single_best_answer','Physiological Adaptation • Spontaneous bacterial peritonitis • Multiple choice A client with cirrhosis and ascites develops fever, diffuse abdominal tenderness, and new confusion. What does the nurse suspect?','Normal ascites|Spontaneous bacterial peritonitis|Esophageal varices|Gallstones    ','B','SBP is an infection of ascitic fluid without an obvious source. Diagnostic paracentesis showing high neutrophil counts confirms it. It can worsen hepatic encephalopathy and requires prompt antibiotics.','Integrated','Adult Health'),
('Set27-RN-9','Physiological Adaptation','Lithium and nephrogenic DI','single_best_answer','Physiological Adaptation • Lithium and nephrogenic DI • Multiple choice A client who has taken lithium for 10 years reports constant thirst and urinating large amounts of dilute urine. What complication does the nurse suspect?','Syndrome of inappropriate ADH|Nephrogenic diabetes insipidus|Acute pancreatitis|Hypoglycemia','B','Long-term lithium can make the kidneys unresponsive to ADH, causing polyuria and polydipsia. Dehydration from polyuria can raise lithium levels and cause toxicity.','Integrated','Adult Health'),
('Set27-RN-10','Physiological Adaptation','Pelvic fracture','single_best_answer','Physiological Adaptation • Pelvic fracture • Multiple choice A client with a pelvic fracture after a motorcycle crash has HR 128/min and BP 88/52 mm Hg. Which complication is the nurse most concerned about?','Fat embolism only|Significant internal hemorrhage|Urinary tract infection|Constipation','B','Pelvic fractures can cause major blood loss from pelvic vessels. Stabilization with a pelvic binder, blood products, and interventional or surgical control may be needed. Bladder and urethral injury are also possible.','Integrated','Adult Health'),
('Set27-RN-11','Pharmacological and Parenteral Therapies','Transfusion thresholds','single_best_answer','Pharmacological and Parenteral Therapies • Transfusion thresholds • Multiple choice A hemodynamically stable adult on a medical unit without active bleeding or cardiac disease has a hemoglobin of 7.6 g/dL. What does the nurse anticipate regarding transfusion?','Immediate transfusion of 2 units|Transfusion is generally not needed, because many guidelines use a threshold of about 7 g/dL for stable clients|Transfusion is always required below 10 g/dL|Platelet transfusion','B','Restrictive transfusion strategies (hemoglobin below about 7 g/dL for stable clients, and about 8 for those with cardiac disease or surgery) are supported by evidence and reduce transfusion risks.','Integrated','Pharmacology'),
('Set27-RN-12','Safety and Infection Control','Prostate brachytherapy','single_best_answer','Safety and Infection Control • Prostate brachytherapy • Multiple choice A client had permanent radioactive seed implants for prostate cancer. Which instruction should the nurse include?','"No precautions are needed."|"Strain your urine for the first few days and don''t touch any seed you find with bare hands. Limit close, prolonged contact with pregnant women and young children for the time recommended."|"Flush any seeds found in your urine."|"Hold young children on your lap for long periods."    ','B','Seeds may pass in urine. Retrieved seeds are handled with a spoon or tweezers and returned per instructions. Radiation from seeds decreases over time, so temporary distance precautions protect vulnerable people.','Integrated','Safety & Infection Control'),
('Set27-RN-13','Pharmacological and Parenteral Therapies','IVIG','single_best_answer','Pharmacological and Parenteral Therapies • IVIG • Multiple choice A client is receiving IV immunoglobulin (IVIG). Which action by the nurse is correct?','Start the infusion at the maximum rate|Start at a slow rate and increase gradually per protocol, monitoring vital signs for infusion reactions such as headache, chills, and hypotension|Mix it with other IV medications|Give it as an IV push','B','IVIG reactions are often rate-related. Gradual titration, premedication when prescribed, adequate hydration, and monitoring reduce complications, which include headache, aseptic meningitis, kidney injury, and thrombosis.','Integrated','Pharmacology'),
('Set27-RN-14','Pharmacological and Parenteral Therapies','Naltrexone','single_best_answer','Pharmacological and Parenteral Therapies • Naltrexone • Multiple choice A client with alcohol use disorder who also takes oxycodone for chronic pain is prescribed naltrexone. What should the nurse do?','Administer both medications together|Clarify the prescription, because naltrexone blocks opioid effects and can cause withdrawal. Clients must be opioid-free for about 7–10 days before starting.|Give naltrexone with alcohol|Double the oxycodone dose','B','Naltrexone is an opioid antagonist. It reduces alcohol cravings but blocks opioid analgesia and can precipitate withdrawal in opioid-dependent clients. Liver function is also monitored.','Integrated','Pharmacology'),
('Set27-RN-15','Psychosocial Integrity','Cognitive behavioral therapy','single_best_answer','Psychosocial Integrity • Cognitive behavioral therapy • Multiple choice A client with depression says, "I made one mistake at work, so I''m a total failure." Which response by the nurse reflects a cognitive behavioral approach?','"Don''t think that way."|"Let''s look at the evidence for and against that thought. Can you think of times you succeeded at work?"|"Maybe you should quit your job."|"Everyone makes mistakes, so forget about it."','B','CBT helps clients identify and challenge distorted automatic thoughts, such as all-or-nothing thinking, and replace them with balanced ones.','Integrated','Mental Health'),
('Set27-RN-16','Reduction of Risk Potential','Neuraxial morphine after cesarean','single_best_answer','Reduction of Risk Potential • Neuraxial morphine after cesarean • Multiple choice A client received intrathecal morphine during spinal anesthesia for a cesarean birth. Which assessment is most important over the next 24 hours?','Pedal pulses every 8 hours|Respiratory rate, oxygen saturation, and sedation level at regular intervals per protocol|Bowel sounds every hour|Temperature only    ','B','Neuraxial morphine provides long-lasting pain relief but can cause delayed respiratory depression up to about 24 hours after the dose. Itching and nausea are common side effects.','Integrated','Adult Health'),
('Set27-RN-17','Health Promotion and Maintenance','Group B streptococcus screening','single_best_answer','Health Promotion and Maintenance • Group B streptococcus screening • Multiple choice A pregnant client asks when she will be tested for group B streptococcus. Which response by the nurse is accurate?','"At the first prenatal visit."|"Between 36 and 37 weeks, with a vaginal-rectal swab."|"Only if you have symptoms."|"At 20 weeks."','B','Universal GBS screening at 36 0/7 to 37 6/7 weeks identifies carriers who need intrapartum antibiotics to prevent early-onset newborn GBS disease.','Integrated','Fundamentals'),
('Set27-RN-18','Physiological Adaptation','Pediatric CPR','single_best_answer','Physiological Adaptation • Pediatric CPR • Multiple choice Two healthcare providers are performing CPR on a 5-year-old. What compression-to-ventilation ratio should they use?','30:2|15:2|5:1|Compressions only with no breaths','B','For two-rescuer CPR on infants and children, the ratio is 15:2. A single rescuer uses 30:2. Compression depth is about one-third of the chest diameter.','Integrated','Adult Health'),
('Set27-RN-19','Physiological Adaptation','Infant CPR','single_best_answer','Physiological Adaptation • Infant CPR • Multiple choice Two healthcare providers are performing CPR on a 6-month-old. Which compression technique is recommended?','The heel of one hand on the lower sternum|The two-thumb, encircling-hands technique just below the nipple line|Compressions over the upper abdomen|Compressions with two hands stacked  ','B','For infants, the two-thumb encircling technique is preferred when two rescuers are present because it produces better perfusion. A single rescuer may use two fingers or the heel of one hand. Depth is about 1.5 inches (4 cm).','Integrated','Adult Health'),
('Set28-RN-1','Management of Care','Prioritization: telemetry','single_best_answer','Management of Care • Prioritization: telemetry • Multiple choice The nurse on a telemetry unit receives report on four clients. Which client should the nurse assess first?','A client taking methadone and IV haloperidol whose QTc has increased to 540 ms, with new runs of polymorphic ventricular beats|A client with stable atrial fibrillation on apixaban whose heart rate is 88/min|A client with first-degree AV block who is asymptomatic|A client with a pacemaker whose rhythm shows consistent capture','A','A markedly prolonged QTc with polymorphic ectopy signals high risk for torsades de pointes, a potentially lethal rhythm. Methadone and haloperidol both prolong the QT interval. The other clients are stable.','Integrated','Management of Care'),
('Set28-RN-2','Pharmacological and Parenteral Therapies','Torsades de pointes','single_best_answer','Pharmacological and Parenteral Therapies • Torsades de pointes • Multiple choice A client with a prolonged QT interval develops torsades de pointes with a pulse. Which medication does the nurse anticipate?','IV magnesium sulfate|IV amiodarone as the first choice|IV procainamide|Oral metoprolol','A','IV magnesium is first-line for torsades de pointes, even when the magnesium level is normal. QT-prolonging drugs are stopped, electrolytes corrected, and defibrillation is used if the client becomes pulseless.','Integrated','Pharmacology'),
('Set28-RN-3','Pharmacological and Parenteral Therapies','Aspirin in acute coronary syndrome','single_best_answer','Pharmacological and Parenteral Therapies • Aspirin in acute coronary syndrome • Multiple choice A client with suspected acute coronary syndrome has no aspirin allergy or active bleeding. How should the nurse give the prescribed aspirin?','Give 81 mg enteric-coated aspirin to swallow whole|Have the client chew non-enteric-coated aspirin (162–325 mg)|Give aspirin rectally only|Give aspirin IV push','B','Chewing non-enteric-coated aspirin speeds absorption and antiplatelet effect in ACS. Enteric coating delays absorption.','Integrated','Pharmacology'),
('Set28-RN-4','Reduction of Risk Potential','Ankle-brachial index','single_best_answer','Reduction of Risk Potential • Ankle-brachial index • Multiple choice A client''s ankle-brachial index (ABI) is 0.62 in the right leg. How should the nurse interpret this?','Normal arterial flow|Moderate peripheral arterial disease|Venous insufficiency|Falsely elevated reading from calcified vessels    ','B','An ABI of about 1.0–1.4 is normal, 0.9 or below indicates PAD, and very low values (below about 0.4) indicate critical limb ischemia. Values above 1.4 suggest noncompressible, calcified arteries.','Integrated','Adult Health'),
('Set28-RN-5','Physiological Adaptation','Massive hemoptysis','single_best_answer','Physiological Adaptation • Massive hemoptysis • Multiple choice A client with known right lung cancer suddenly coughs up large amounts of bright red blood. After calling for help, how should the nurse position the client?','Lying on the left side with the right lung up|Lying on the right side (affected lung down)|Prone|Flat on the back','B','Positioning with the bleeding lung down uses gravity to protect the unaffected lung from blood. Airway protection, suction, and emergency interventions follow.','Integrated','Adult Health'),
('Set28-RN-6','Reduction of Risk Potential','Prone positioning in ARDS','single_best_answer','Reduction of Risk Potential • Prone positioning in ARDS • Multiple choice A client with severe ARDS is placed in the prone position. Which nursing action is most important?','Turn the client prone only for 5 minutes each day|Frequently assess and protect pressure points on the face, chest, knees, and other bony areas, and secure all tubes and lines|Remove the endotracheal tube securing device|Stop all sedation','B','Prone positioning improves oxygenation and survival in severe ARDS, but it increases the risk of facial and anterior pressure injuries and tube dislodgement. Clients typically remain prone for 12–16 hours or more per day.','Integrated','Adult Health'),
('Set28-RN-7','Physiological Adaptation','Giant cell arteritis','single_best_answer','Physiological Adaptation • Giant cell arteritis • Multiple choice A 72-year-old reports a new temporal headache, scalp tenderness, and jaw pain when chewing. Which complication is the nurse most concerned about, and what treatment is anticipated?','Hearing loss; antibiotics|Permanent vision loss; urgent high-dose corticosteroids|Stroke; thrombolytics|Migraine; triptans','B','Giant cell (temporal) arteritis can cause sudden, irreversible blindness. Corticosteroids are started promptly, often before the temporal artery biopsy, and an elevated ESR supports the diagnosis.','Integrated','Adult Health'),
('Set28-RN-8','Reduction of Risk Potential','Diabetic foot ulcer','single_best_answer','Reduction of Risk Potential • Diabetic foot ulcer • Multiple choice A client with diabetes has a plantar foot ulcer. Which intervention is most important for healing?','Walking barefoot to toughen the skin|Offloading pressure from the ulcer as prescribed (such as a total contact cast or offloading boot), with glucose control and wound care|Soaking the foot in hot water daily|Applying a tight elastic bandage over the ulcer    ','B','Continued pressure prevents healing. Offloading, infection control, debridement, adequate circulation, and glucose control promote healing and reduce amputation risk.','Integrated','Adult Health'),
('Set28-RN-9','Reduction of Risk Potential','ERCP','single_best_answer','Reduction of Risk Potential • ERCP • Multiple choice A client had an endoscopic retrograde cholangiopancreatography (ERCP) to remove a bile duct stone. Four hours later, the client reports severe epigastric pain radiating to the back. What does the nurse suspect?','Expected mild discomfort|Post-ERCP pancreatitis|Gastroenteritis|Myocardial infarction only','B','Pancreatitis is the most common complication after ERCP. The nurse reports severe pain, checks lipase as prescribed, and monitors for perforation and bleeding.','Integrated','Adult Health'),
('Set28-RN-10','Health Promotion and Maintenance','Enhanced recovery after surgery','single_best_answer','Health Promotion and Maintenance • Enhanced recovery after surgery • Multiple choice A client is on an enhanced recovery after surgery (ERAS) pathway following colon resection. Which intervention does the nurse expect?','Prolonged NPO status for several days|Early oral intake, early ambulation, and multimodal pain control that minimizes opioids|Strict bed rest for 3 days|Routine NG tube for a week','B','ERAS pathways shorten length of stay and reduce complications through early feeding, mobility, limited opioids, and avoiding routine drains and tubes.','Integrated','Fundamentals'),
('Set28-RN-11','Pharmacological and Parenteral Therapies','ACE inhibitors and renal artery stenosis','single_best_answer','Pharmacological and Parenteral Therapies • ACE inhibitors and renal artery stenosis • Multiple choice A client with bilateral renal artery stenosis was started on lisinopril 1 week ago. The creatinine has risen from 1.1 to 2.4 mg/dL. What should the nurse do?','Continue the medication and recheck in a month|Hold the medication and notify the provider, because ACE inhibitors can cause acute kidney injury in bilateral renal artery stenosis|Double the dose|Encourage a high-potassium diet','B','In bilateral renal artery stenosis, the kidneys depend on angiotensin II to maintain filtration. Blocking it can sharply reduce kidney function.','Integrated','Pharmacology'),
('Set28-RN-12','Physiological Adaptation','Lumbar spinal stenosis','single_best_answer','Physiological Adaptation • Lumbar spinal stenosis • Multiple choice A client reports leg pain and numbness when walking that is relieved by sitting or bending forward. Pedal pulses are strong. What does the nurse suspect?','Peripheral arterial disease|Lumbar spinal stenosis (neurogenic claudication)|Deep vein thrombosis|Gout    ','B','Neurogenic claudication improves with spinal flexion, such as leaning on a shopping cart, because it opens the spinal canal. Vascular claudication improves with standing still and is associated with weak pulses.','Integrated','Adult Health'),
('Set28-RN-13','Pharmacological and Parenteral Therapies','Elevated INR without bleeding','single_best_answer','Pharmacological and Parenteral Therapies • Elevated INR without bleeding • Multiple choice A client taking warfarin has an INR of 5.2 with no signs of bleeding. What does the nurse anticipate?','Administering IV vitamin K and plasma immediately|Holding one or more warfarin doses, rechecking the INR, and assessing for bleeding, with low-dose oral vitamin K considered by the provider|Increasing the warfarin dose|No change in management','B','For a supratherapeutic INR without bleeding, holding doses and close monitoring are usually sufficient. Rapid reversal is reserved for serious bleeding.','Integrated','Pharmacology'),
('Set28-RN-14','Basic Care and Comfort','Cancer-related fatigue','single_best_answer','Basic Care and Comfort • Cancer-related fatigue • Multiple choice A client receiving radiation therapy reports overwhelming fatigue. Which recommendation is best supported by evidence?','Complete bed rest until treatment ends|Light to moderate physical activity as tolerated, such as short daily walks, with planned rest periods|Drink several energy drinks daily|Avoid all activity','B','Regular moderate exercise reduces cancer-related fatigue. Energy conservation, sleep hygiene, and treating contributing factors such as anemia also help.','Integrated','Adult Health'),
('Set28-RN-15','Health Promotion and Maintenance','HIV in pregnancy','single_best_answer','Health Promotion and Maintenance • HIV in pregnancy • Multiple choice A pregnant client with HIV asks how to reduce the chance of passing HIV to her baby. Which information should the nurse include?','"Stop your HIV medications during pregnancy."|"Take antiretroviral therapy throughout pregnancy. Your baby will receive antiretroviral medication after birth, and in the U.S., formula feeding is usually recommended."|"Breastfeeding is recommended to boost your baby''s immunity."|"Transmission can''t be prevented."','B','ART with viral suppression, newborn prophylaxis, and avoiding breastfeeding reduce perinatal transmission to below 1%. Current guidance supports shared decision-making about breastfeeding for people with sustained viral suppression.','Integrated','Fundamentals'),
('Set28-RN-16','Pharmacological and Parenteral Therapies','Prazosin for PTSD nightmares','single_best_answer','Pharmacological and Parenteral Therapies • Prazosin for PTSD nightmares • Multiple choice A veteran with PTSD is prescribed prazosin for nightmares. Which instruction should the nurse include?','"Take it in the morning."|"Take it at bedtime, and get up slowly, especially after the first dose, because it can cause dizziness or fainting."|"It will stop your nightmares immediately."|"Stop it suddenly if you feel dizzy."    ','B','Prazosin, an alpha-1 blocker, can cause first-dose orthostatic hypotension. Bedtime dosing and gradual titration reduce risk.','Integrated','Pharmacology'),
('Set28-RN-17','Psychosocial Integrity','Non-suicidal self-injury','single_best_answer','Psychosocial Integrity • Non-suicidal self-injury • Multiple choice An adolescent comes to the clinic with several superficial cuts on the forearm and says they "help me feel better." What is the nurse''s best approach?','Express shock and disapproval|Provide wound care in a calm, nonjudgmental way, and directly assess for suicidal thoughts and emotional distress|Ignore the cuts to avoid reinforcing the behavior|Tell the adolescent to promise never to do it again','B','A nonjudgmental approach builds trust. Self-injury may be a way of coping with distress and is associated with increased suicide risk, so a risk assessment and mental health referral are needed.','Integrated','Mental Health'),
('Set28-RN-18','Pharmacological and Parenteral Therapies','Carboprost','single_best_answer','Pharmacological and Parenteral Therapies • Carboprost • Multiple choice A client with postpartum hemorrhage from uterine atony has a history of severe asthma. Which uterotonic should the nurse question?','Oxytocin|Carboprost tromethamine|Misoprostol|Tranexamic acid','B','Carboprost (a prostaglandin F2-alpha analog) can cause bronchospasm and is contraindicated in asthma. Methylergonovine is avoided in hypertension.','Integrated','Pharmacology'),
('Set28-RN-19','Health Promotion and Maintenance','Infant reflux','single_best_answer','Health Promotion and Maintenance • Infant reflux • Multiple choice The parent of a thriving 2-month-old with frequent spitting up asks whether the baby should sleep on the stomach or with the head elevated. What should the nurse advise?','"Place the baby on the stomach to sleep."|"Continue placing the baby on the back on a flat, firm surface. Hold the baby upright after feedings, feed smaller amounts more often, and burp frequently."|"Use a wedge in the crib."|"Let the baby sleep in the car seat."  ','B','Spitting up is common and usually resolves by about 12 months. Safe sleep recommendations still apply. Positioners and inclined sleepers increase suffocation risk. Poor weight gain or feeding refusal should be reported.','Integrated','Fundamentals'),
('Set29-RN-1','Management of Care','Prioritization: respiratory clinic','single_best_answer','Management of Care • Prioritization: respiratory clinic • Multiple choice The nurse in a pulmonary clinic receives four phone calls. Which client should the nurse call back first?','A client with asthma who has used the albuterol inhaler every hour for 6 hours and still feels short of breath|A client with COPD requesting a refill of tiotropium|A client with sleep apnea whose CPAP mask is uncomfortable|A client with a cough asking whether to get a flu shot','A','Needing a rescue inhaler repeatedly with persistent symptoms indicates a severe, poorly controlled exacerbation that needs urgent evaluation. The other calls are routine.','Integrated','Management of Care'),
('Set29-RN-2','Pharmacological and Parenteral Therapies','Heart failure therapy','single_best_answer','Pharmacological and Parenteral Therapies • Heart failure therapy • Multiple choice A client with heart failure with reduced ejection fraction, who does not have diabetes, is prescribed dapagliflozin. The client asks why a "diabetes pill" was prescribed. What is the nurse''s best response?','"This must be a mistake."|"This medication class has been shown to reduce hospitalizations and death in heart failure, whether or not a person has diabetes."|"It will lower your blood sugar to prevent diabetes."|"It replaces all your other heart medications."','B','SGLT2 inhibitors are now a core part of heart failure therapy. The nurse teaches genital hygiene, hydration, and sick-day precautions.','Integrated','Pharmacology'),
('Set29-RN-3','Pharmacological and Parenteral Therapies','IV nitroglycerin','single_best_answer','Pharmacological and Parenteral Therapies • IV nitroglycerin • Multiple choice A client is receiving an IV nitroglycerin infusion for unstable angina. Which nursing action is correct?','Titrate without monitoring BP|Use the manufacturer-supplied or non-PVC tubing if required, and monitor BP closely while titrating to relieve chest pain|Give it by IV push|Stop the infusion abruptly if pain resolves','B','Standard PVC tubing can absorb nitroglycerin, reducing the delivered dose. Hypotension and headache are common side effects, and PDE-5 inhibitor use is a contraindication.','Integrated','Pharmacology'),
('Set29-RN-4','Reduction of Risk Potential','Pulmonary function tests','single_best_answer','Reduction of Risk Potential • Pulmonary function tests • Multiple choice A client''s spirometry shows a post-bronchodilator FEV1/FVC ratio of 0.58. How should the nurse interpret this?','Normal lung function|Airflow obstruction consistent with COPD|A restrictive lung disease pattern|Improved asthma control    ','B','A post-bronchodilator FEV1/FVC below 0.70 confirms persistent airflow limitation, consistent with COPD. Restrictive diseases reduce both values proportionally.','Integrated','Adult Health'),
('Set29-RN-5','Safety and Infection Control','Halo vest','single_best_answer','Safety and Infection Control • Halo vest • Multiple choice A client with a cervical spine fracture has a halo vest. Which item must be kept with the client at all times?','A pair of scissors|The wrench (or tool) to release the vest''s anterior bars in an emergency such as CPR|A cervical collar|Extra pins','B','The wrench allows rapid access to the chest for CPR. The nurse also performs pin site care, checks the skin under the vest, and never uses the halo frame to lift or turn the client.','Integrated','Safety & Infection Control'),
('Set29-RN-6','Pharmacological and Parenteral Therapies','Parkinson''s disease drug interactions','single_best_answer','Pharmacological and Parenteral Therapies • Parkinson''s disease drug interactions • Multiple choice A client with Parkinson''s disease has postoperative nausea. Which prescribed antiemetic should the nurse question?','Ondansetron|Metoclopramide|Nonpharmacological measures such as ginger|Trimethobenzamide','B','Metoclopramide, haloperidol, and prochlorperazine block dopamine and can worsen parkinsonian symptoms. Ondansetron is generally preferred.','Integrated','Pharmacology'),
('Set29-RN-7','Pharmacological and Parenteral Therapies','Pheochromocytoma','single_best_answer','Pharmacological and Parenteral Therapies • Pheochromocytoma • Multiple choice A client with pheochromocytoma is scheduled for adrenalectomy. Which medication sequence does the nurse anticipate before surgery?','A beta blocker first, then an alpha blocker|An alpha blocker (such as phenoxybenzamine) first, then a beta blocker if needed for tachycardia|A beta blocker alone|No medications before surgery','B','Starting a beta blocker first leaves alpha-mediated vasoconstriction unopposed and can cause a hypertensive crisis. Alpha blockade with volume expansion comes first.','Integrated','Pharmacology'),
('Set29-RN-8','Pharmacological and Parenteral Therapies','Rifaximin','single_best_answer','Pharmacological and Parenteral Therapies • Rifaximin • Multiple choice A client with cirrhosis and recurrent hepatic encephalopathy is prescribed rifaximin in addition to lactulose. How does the nurse explain its purpose?','"It lowers your blood pressure."|"It is an antibiotic that reduces ammonia-producing bacteria in the gut and helps prevent episodes of confusion."|"It replaces the need for lactulose."|"It treats liver scarring."    ','B','Rifaximin is minimally absorbed and acts locally in the gut. It is often combined with lactulose to reduce encephalopathy recurrence.','Integrated','Pharmacology'),
('Set29-RN-9','Reduction of Risk Potential','Whipple procedure','single_best_answer','Reduction of Risk Potential • Whipple procedure • Multiple choice A client had a pancreaticoduodenectomy (Whipple procedure) for pancreatic cancer. Which finding requires prompt follow-up?','Glucose of 118 mg/dL|Clear, amber-colored drainage from the abdominal drain that tests high in amylase, with increasing abdominal pain|Incisional pain rated 4/10 with medication|Hypoactive bowel sounds on day 1','B','Drainage high in amylase suggests a pancreatic anastomotic leak (fistula), a serious complication. The nurse also monitors glucose closely because pancreatic tissue was removed.','Integrated','Adult Health'),
('Set29-RN-10','Physiological Adaptation','Access site bleeding after dialysis','single_best_answer','Physiological Adaptation • Access site bleeding after dialysis • Multiple choice After hemodialysis needles are removed, a client''s arteriovenous fistula site continues to bleed steadily. What should the nurse do first?','Apply a tourniquet above the fistula|Apply firm, direct pressure to the site without occluding flow through the fistula, and notify the provider if bleeding persists|Elevate the arm and leave it uncovered|Apply ice and walk away','B','Direct pressure controls bleeding. Complete occlusion or a tourniquet can clot the fistula. Prolonged bleeding may indicate excess anticoagulation or access problems.','Integrated','Adult Health'),
('Set29-RN-11','Health Promotion and Maintenance','Bladder cancer','single_best_answer','Health Promotion and Maintenance • Bladder cancer • Multiple choice A 66-year-old with a 40 pack-year smoking history reports painless blood in the urine. What should the nurse recognize?','Painless hematuria is always harmless|Painless hematuria is the most common sign of bladder cancer, and smoking is its leading risk factor, so evaluation is needed|The hematuria is likely from dehydration only|Only painful hematuria needs evaluation','B','Gross hematuria in adults requires evaluation, often including cystoscopy and imaging. Smoking cessation lowers bladder cancer risk.','Integrated','Fundamentals'),
('Set29-RN-12','Health Promotion and Maintenance','Fracture healing','single_best_answer','Health Promotion and Maintenance • Fracture healing • Multiple choice A client with a tibial fracture asks what might slow bone healing. Which factor should the nurse emphasize?','Drinking milk|Cigarette smoking|Wearing the cast as directed|Taking prescribed vitamin D    ','B','Smoking impairs blood flow and bone formation, increasing the risk of delayed healing and nonunion. Diabetes, malnutrition, and steroids also slow healing.','Integrated','Fundamentals'),
('Set29-RN-13','Reduction of Risk Potential','Absolute neutrophil count','single_best_answer','Reduction of Risk Potential • Absolute neutrophil count • Multiple choice A client''s WBC is 2,000/mm³ with 20% segmented neutrophils and 5% bands. What is the absolute neutrophil count, and what precautions are needed?','ANC 500; severe neutropenia requiring neutropenic precautions|ANC 1,000; no risk|ANC 2,000; normal|ANC 100; no precautions needed','A','ANC = WBC × (% neutrophils + % bands) = 2,000 × 0.25 = 500/mm³. An ANC of 500 or below is severe neutropenia with high infection risk.','Integrated','Adult Health'),
('Set29-RN-14','Health Promotion and Maintenance','Cervical cancer screening','single_best_answer','Health Promotion and Maintenance • Cervical cancer screening • Multiple choice A 35-year-old with normal previous results asks how often she needs cervical cancer screening. Which response by the nurse reflects current guidance for average-risk adults?','"Every year with a Pap test."|"Every 5 years with an HPV test (alone or with a Pap test), or every 3 years with a Pap test alone."|"Screening stops at age 30."|"Only if you have symptoms."','B','For ages 30–65, USPSTF recommends a Pap test every 3 years, primary HPV testing every 5 years, or co-testing every 5 years. For ages 21–29, a Pap test is done every 3 years.','Integrated','Fundamentals'),
('Set29-RN-15','Pharmacological and Parenteral Therapies','Cyclosporine','single_best_answer','Pharmacological and Parenteral Therapies • Cyclosporine • Multiple choice A client taking cyclosporine after a kidney transplant has several findings. Which one is most concerning?','Mild increase in hair growth|Gum overgrowth|Rising serum creatinine and BP|Mild tremor','C','Cyclosporine is nephrotoxic and causes hypertension. Rising creatinine may indicate toxicity or rejection and requires drug level monitoring and provider evaluation. Hair growth, gum hyperplasia, and tremor are known side effects.','Integrated','Pharmacology'),
('Set29-RN-16','Psychosocial Integrity','Suicide risk factors','single_best_answer','Psychosocial Integrity • Suicide risk factors • Multiple choice Which client has the highest risk for suicide?','A 30-year-old woman with seasonal allergies|A 78-year-old widowed man with chronic pain, alcohol use, and access to a firearm|A 22-year-old college student with exam stress and strong family support|A 45-year-old with well-controlled hypertension    ','B','Older age, male sex, being widowed, chronic illness or pain, substance use, and access to lethal means (especially firearms) all increase suicide risk.','Integrated','Mental Health'),
('Set29-RN-17','Reduction of Risk Potential','External cephalic version','single_best_answer','Reduction of Risk Potential • External cephalic version • Multiple choice A client at 37 weeks'' gestation is scheduled for external cephalic version for breech presentation. Which action does the nurse anticipate?','No fetal monitoring is needed|A nonstress test or ultrasound before and fetal monitoring after, a tocolytic as prescribed, and Rh immune globulin if the client is Rh-negative|A vaginal exam every 5 minutes during the procedure|Discharge immediately without monitoring','B','Version can cause fetal heart rate changes, placental abruption, or fetal-maternal bleeding. Monitoring, uterine relaxation, and Rh prophylaxis are standard.','Integrated','Adult Health'),
('Set29-RN-18','Reduction of Risk Potential','Cystic fibrosis diagnosis','single_best_answer','Reduction of Risk Potential • Cystic fibrosis diagnosis • Multiple choice A child with poor weight gain, frequent respiratory infections, and salty-tasting skin is being evaluated for cystic fibrosis. Which test confirms the diagnosis?','Sweat chloride test|Tuberculin skin test|Hemoglobin electrophoresis|Urine culture','A','Elevated sweat chloride confirms CF. Newborn screening and genetic testing are also used.','Integrated','Adult Health'),
('Set29-RN-19','Pharmacological and Parenteral Therapies','Pediatric iron supplement safety','single_best_answer','Pharmacological and Parenteral Therapies • Pediatric iron supplement safety • Multiple choice A 9-month-old is prescribed an iron supplement. Which instruction is most important for the nurse to give?','"Give it with milk."|"Store it locked and out of reach, because iron overdose is dangerous for young children. Give it between meals with juice if tolerated."|"Double the dose if a dose is missed."|"Mix it into a full bottle."  ','B','Iron is a leading cause of poisoning deaths in young children. Milk reduces absorption, and missed doses are not doubled.','Integrated','Pharmacology'),
('Set30-RN-1','Management of Care','Prioritization: endocrine','single_best_answer','Management of Care • Prioritization: endocrine • Multiple choice The nurse receives report on four clients. Which client should the nurse assess first?','A client with SIADH whose sodium is 118 mEq/L, with new confusion and muscle twitching|A client with central diabetes insipidus who is stable on desmopressin|A client with hypothyroidism who started levothyroxine yesterday|A client with Cushing''s syndrome whose glucose is 190 mg/dL','A','Severe hyponatremia with neurological changes can progress to seizures and cerebral edema. The other clients are stable.','Integrated','Management of Care'),
('Set30-RN-2','Physiological Adaptation','Pulsus paradoxus','single_best_answer','Physiological Adaptation • Pulsus paradoxus • Multiple choice A client with a large pericardial effusion is being evaluated for cardiac tamponade. Which finding supports tamponade?','Systolic BP that falls more than 10 mm Hg during inspiration|Bradycardia with hypertension|Bounding peripheral pulses|A loud S4 heart sound','A','Pulsus paradoxus (an exaggerated inspiratory drop in systolic BP) is a classic sign of tamponade, along with Beck''s triad of hypotension, JVD, and muffled heart sounds. Pericardiocentesis is the treatment.','Integrated','Adult Health'),
('Set30-RN-3','Pharmacological and Parenteral Therapies','Beta blocker overdose','single_best_answer','Pharmacological and Parenteral Therapies • Beta blocker overdose • Multiple choice A client took an overdose of propranolol and has HR 38/min and BP 70/40 mm Hg despite atropine and IV fluids. Which medication does the nurse anticipate?','Glucagon IV|Naloxone|Flumazenil|Protamine sulfate','A','Glucagon increases heart rate and contractility through a pathway that bypasses beta receptors. High-dose insulin with dextrose, vasopressors, and pacing may also be used.','Integrated','Pharmacology'),
('Set30-RN-4','Pharmacological and Parenteral Therapies','Thrombolytic contraindications','single_best_answer','Pharmacological and Parenteral Therapies • Thrombolytic contraindications • Multiple choice A client with a massive pulmonary embolism and hypotension is being considered for systemic thrombolysis. Which finding in the history is a contraindication the nurse should report?','Seasonal allergies|A hemorrhagic stroke 2 months ago|Controlled hypertension|A history of appendectomy 20 years ago    ','B','Prior intracranial hemorrhage, recent ischemic stroke, active bleeding, recent major surgery or trauma, and intracranial tumors are contraindications to thrombolysis because of bleeding risk.','Integrated','Pharmacology'),
('Set30-RN-5','Pharmacological and Parenteral Therapies','Dexamethasone for brain tumor','single_best_answer','Pharmacological and Parenteral Therapies • Dexamethasone for brain tumor • Multiple choice A client with a brain tumor is prescribed dexamethasone. Which action is most important for the nurse to include?','Restrict the client to bed rest|Monitor blood glucose and watch for signs of infection|Give it at bedtime on an empty stomach|Stop it abruptly once the headache improves','B','Dexamethasone reduces vasogenic cerebral edema but causes hyperglycemia, immunosuppression, and GI irritation. It is taken with food, usually in the morning, and tapered rather than stopped abruptly.','Integrated','Pharmacology'),
('Set30-RN-6','Safety and Infection Control','Tetanus prophylaxis','single_best_answer','Safety and Infection Control • Tetanus prophylaxis • Multiple choice A 40-year-old who has never received a tetanus vaccine steps on a rusty nail in a barn. What does the nurse anticipate?','No treatment is needed|A tetanus-containing vaccine (Tdap) plus tetanus immune globulin, with the vaccine series completed later|Antibiotics only|Tetanus immune globulin only','B','For dirty or contaminated wounds, people with fewer than three prior tetanus doses or an unknown history need both a vaccine and tetanus immune globulin for immediate passive protection.','Integrated','Safety & Infection Control'),
('Set30-RN-7','Pharmacological and Parenteral Therapies','Inpatient insulin regimens','single_best_answer','Pharmacological and Parenteral Therapies • Inpatient insulin regimens • Multiple choice A hospitalized client with type 2 diabetes who is eating regular meals has glucose values in the 250s. Which regimen does the nurse anticipate based on current recommendations?','Sliding-scale regular insulin alone|Scheduled basal insulin plus mealtime (prandial) insulin, with correction doses as needed|Stopping all insulin|Oral glucose tablets','B','Sliding-scale insulin alone is discouraged because it reacts to hyperglycemia instead of preventing it. Basal-bolus regimens improve glycemic control in eating clients.','Integrated','Pharmacology'),
('Set30-RN-8','Reduction of Risk Potential','NG tube suction','single_best_answer','Reduction of Risk Potential • NG tube suction • Multiple choice A client has a single-lumen (Levin) nasogastric tube for gastric decompression. Which suction setting does the nurse expect?','High continuous suction|Low intermittent suction|No suction ever|Wall suction at 200 mm Hg continuous    ','B','Continuous suction through a single-lumen tube can pull the gastric mucosa against the tube and damage it. Double-lumen sump tubes (Salem sump) can use low continuous suction because the air vent protects the mucosa.','Integrated','Adult Health'),
('Set30-RN-9','Pharmacological and Parenteral Therapies','Acetaminophen in liver disease','single_best_answer','Pharmacological and Parenteral Therapies • Acetaminophen in liver disease • Multiple choice A client with compensated cirrhosis asks about pain relief for a headache. Which response by the nurse is most appropriate?','"Take ibuprofen, since it''s safest for your liver."|"Acetaminophen may be used at a reduced maximum dose, often no more than 2 g per day, as directed by your provider. Avoid alcohol."|"Take as much acetaminophen as you need."|"No pain relievers are ever safe."','B','Low-dose acetaminophen is often preferred in cirrhosis. NSAIDs can cause kidney injury, GI bleeding, and fluid retention in liver disease.','Integrated','Pharmacology'),
('Set30-RN-10','Physiological Adaptation','TUR syndrome','single_best_answer','Physiological Adaptation • TUR syndrome • Multiple choice During recovery from a transurethral resection of the prostate, the client becomes confused and nauseated, with bradycardia and hypertension. The sodium is 124 mEq/L. What does the nurse suspect?','Normal postoperative confusion|Transurethral resection (TUR) syndrome from absorption of irrigation fluid|Urinary tract infection|Hypoglycemia','B','Absorption of hypotonic irrigation fluid during TURP can cause fluid overload and dilutional hyponatremia. It is managed with fluid restriction, diuretics, and cautious sodium correction.','Integrated','Adult Health'),
('Set30-RN-11','Pharmacological and Parenteral Therapies','Bisphosphonates and dental care','single_best_answer','Pharmacological and Parenteral Therapies • Bisphosphonates and dental care • Multiple choice A client with cancer metastatic to bone is starting IV zoledronic acid. Which teaching point is most important?','"Avoid dental care entirely."|"Have a dental exam before starting, keep up with good oral hygiene, and tell your dentist you take this drug, because it increases the risk of jaw osteonecrosis."|"Take it with orange juice."|"It will increase your calcium level."','B','Osteonecrosis of the jaw is a rare but serious effect, especially with IV bisphosphonates and invasive dental procedures. Kidney function and calcium are also monitored, because the drug can cause hypocalcemia.','Integrated','Pharmacology'),
('Set30-RN-12','Pharmacological and Parenteral Therapies','Febrile nonhemolytic transfusion reaction','single_best_answer','Pharmacological and Parenteral Therapies • Febrile nonhemolytic transfusion reaction • Multiple choice A client has had two previous febrile reactions (fever and chills without hemolysis) during transfusions. Which strategy does the nurse anticipate for future transfusions?','No blood transfusions ever|Leukocyte-reduced blood products and premedication with an antipyretic as prescribed|Transfusing faster|Using D5W to prime the tubing    ','B','Febrile nonhemolytic reactions are caused by cytokines and white cells in the product. Leukoreduction reduces risk. Any fever during a transfusion still requires stopping the transfusion to rule out hemolysis.','Integrated','Pharmacology'),
('Set30-RN-13','Safety and Infection Control','Chemotherapy-induced peripheral neuropathy','single_best_answer','Safety and Infection Control • Chemotherapy-induced peripheral neuropathy • Multiple choice A client receiving paclitaxel reports numbness and tingling in the feet. Which instruction should the nurse include?','"Walk barefoot to improve sensation."|"Inspect your feet daily, wear protective shoes, check bath water temperature with your elbow or a thermometer, and report worsening symptoms."|"Use a heating pad on your feet."|"The numbness means the chemotherapy isn''t working."','B','Decreased sensation increases the risk of injuries and burns. Worsening neuropathy may require a dose adjustment.','Integrated','Safety & Infection Control'),
('Set30-RN-14','Safety and Infection Control','Contrast allergy','single_best_answer','Safety and Infection Control • Contrast allergy • Multiple choice A client with a history of hives after IV contrast is scheduled for a contrast CT. What does the nurse anticipate?','Proceed without any changes|Notify the radiology team and provider, who may prescribe premedication (such as a corticosteroid and antihistamine) or an alternative study|Give the contrast faster|Cancel all future imaging permanently','B','Prior reactions increase risk. Premedication protocols or alternative imaging reduce risk, and emergency medications must be available.','Integrated','Safety & Infection Control'),
('Set30-RN-15','Pharmacological and Parenteral Therapies','SSRIs in adolescents','single_best_answer','Pharmacological and Parenteral Therapies • SSRIs in adolescents • Multiple choice A 15-year-old is starting fluoxetine for depression. Which instruction is most important for the nurse to give the parents?','"It works within 24 hours."|"Watch closely for worsening depression, agitation, or suicidal thoughts, especially in the first few weeks and after dose changes, and report them immediately."|"Stop it if your teen feels better after a week."|"No monitoring is needed."','B','Antidepressants carry a boxed warning for increased suicidal thinking in children, adolescents, and young adults. Close monitoring is essential, especially early in treatment.','Integrated','Pharmacology'),
('Set30-RN-16','Psychosocial Integrity','Professional boundaries','single_best_answer','Psychosocial Integrity • Professional boundaries • Multiple choice A client being discharged offers the nurse an expensive watch as thanks. What is the nurse''s best response?','Accept the watch to avoid offending the client|Thank the client warmly, explain that nurses can''t accept gifts like this, and follow facility policy|Ask the client for a different gift|Accept it but don''t tell anyone    ','B','Accepting significant gifts can blur professional boundaries. Most policies allow only small tokens, such as cards or treats shared with the unit.','Integrated','Mental Health'),
('Set30-RN-17','Pharmacological and Parenteral Therapies','Antepartum Rh immune globulin','single_best_answer','Pharmacological and Parenteral Therapies • Antepartum Rh immune globulin • Multiple choice An Rh-negative client with a negative antibody screen is at 28 weeks'' gestation. What does the nurse anticipate?','No Rh immune globulin until after delivery|Administering Rh(D) immune globulin now, with another dose after birth if the newborn is Rh-positive|Administering Rh immune globulin to the partner|Giving it only if bleeding occurs','B','Routine prophylaxis at about 28 weeks prevents sensitization from small fetal-maternal bleeds in the third trimester. A postpartum dose is given within 72 hours if the newborn is Rh-positive.','Integrated','Pharmacology'),
('Set30-RN-18','Pharmacological and Parenteral Therapies','Newborn of a mother with hepatitis B','single_best_answer','Pharmacological and Parenteral Therapies • Newborn of a mother with hepatitis B • Multiple choice A newborn''s mother is positive for hepatitis B surface antigen. What does the nurse anticipate for the newborn?','No treatment until age 1|Hepatitis B vaccine and hepatitis B immune globulin within 12 hours of birth|Formula feeding is required|Isolation from the mother','B','Prompt vaccination with HBIG greatly reduces perinatal transmission. Breastfeeding is not contraindicated. The infant completes the vaccine series and is tested afterward.','Integrated','Pharmacology'),
('Set30-RN-19','Physiological Adaptation','Infant hydrocephalus','single_best_answer','Physiological Adaptation • Infant hydrocephalus • Multiple choice Which findings in a 3-month-old should the nurse report as possible signs of hydrocephalus?','A flat anterior fontanel and steady head growth|Rapidly increasing head circumference, a bulging fontanel, separated sutures, and eyes deviated downward (sunset eyes)|Head circumference in the 50th percentile|A social smile  ','B','Because infant skulls can expand, increasing head size is an early sign. Irritability, poor feeding, and a high-pitched cry may also occur.','Integrated','Adult Health')
) x(src,client_need,topic,item_type,stem,opts,keys,rationale,body_system,discipline) loop
 qid:=md5('rnmaster-'||lower(r.src))::uuid; qvid:=md5('rnmaster-v-'||lower(r.src))::uuid;
 insert into public.questions(id,slug,lifecycle_status,current_version) values(qid,'rnmaster-'||lower(r.src),'pilot',1) on conflict(slug) do update set updated_at=now() returning id into qid;
 keyarr:=string_to_array(r.keys,',');
 insert into public.question_versions(id,question_id,version,stem,item_type,exam_tracks,subject,topic,client_need,difficulty,rationale_correct,rationale_distractors,memory_rule,source_note,validation_status,professional_role_focus,track_rationale,body_system,discipline,source_id,response_config,scoring_method)
 values(qvid,qid,1,r.stem,r.item_type,array['rn'],r.client_need,r.topic,r.client_need,'medium',r.rationale,'Each distractor must be evaluated against the clinical task and source rationale.','Identify the task, interpret the cues, and compare every option with the safest evidence-based RN response.','User-provided NCLEX-RN Master Edition; loaded as PILOT pending clinical/editorial validation. Not human or psychometrically validated.','pilot','Entry-level RN clinical judgment.','NCLEX-RN',r.body_system,r.discipline,'RNMaster-'||r.src,'{}'::jsonb,case when r.item_type='multiple_response' then 'plus_minus' else 'zero_one' end)
 on conflict(question_id,version) do update set stem=excluded.stem,item_type=excluded.item_type,source_id=excluded.source_id,validation_status='pilot' returning id into qvid;
 delete from public.question_options where question_version_id=qvid; n:=0;
 for optrec in select unnest(string_to_array(r.opts,'|')) as txt loop n:=n+1; insert into public.question_options(question_version_id,option_key,option_text,is_correct,rationale,display_order) values(qvid,chr(96+n),optrec.txt,(upper(chr(96+n))=any(keyarr)),case when upper(chr(96+n))=any(keyarr) then r.rationale else null end,n); end loop;
 select count(*) filter(where is_correct) into kc from public.question_options where question_version_id=qvid;
 if (r.item_type='single_best_answer' and kc<>1) or (r.item_type='multiple_response' and kc<2) then raise exception 'Key integrity failed %',r.src; end if;
 update public.question_versions set key_consistency_status='pass',key_consistency_checked_at=now(),key_consistency_notes='Source key/options passed deterministic consistency validation; clinical review pending.' where id=qvid;
end loop;
end $$;
commit;